export const onekick_h: string = "/* Shared logic for the 01_OneKick example.\n *\n * The whole program is one voice and a render function, kept in a header\n * so the .ino and the size-report sketch (test/sketches/p4_e1_onekick.cpp)\n * compile the same code and the reported cost is the real one.\n *\n * This is the smallest useful bellows program, and it is the number the\n * rest of the library is measured against: one kick, one include, no\n * registry, no dispatch table. Measured on Cortex-M7 at -Os with\n * --gc-sections, as the p4_e1_onekick row of tools/size-report.sh:\n *\n *     flash 3776 B    RAM 1100 B\n *\n * The 16 bytes over the s1_kick row's 3760 B are this wrapper class and\n * the non-default Params below; a bare Kick with stock parameters is the\n * 3760 B floor.\n *\n * Note what is not here. There is no engine lookup by name, no base class\n * and no virtual call. Kick is a concrete type, the compiler can see\n * every call into it, and the linker never learns that Snare and Hat\n * exist even though they live in the same header. */\n#pragma once\n\n#include \"bellows/engines/drums.h\"\n\nnamespace onekick {\n\n/* A render object: any callable with the library's block signature works\n * as the Render template argument for the Teensy and Daisy adapters. */\nclass Voice {\n public:\n  void Init(float sample_rate) {\n    /* Params defaults match the ParamSpec defaults in the TypeScript\n     * drums.ts exactly, so this kick sounds like the browser one. */\n    bellows::Kick::Params p;\n    p.decay = 0.55f;      /* a little longer than the 0.4 default */\n    p.drive = 3.0f;       /* and pushed harder into the tanh */\n    kick_.Init(sample_rate, p);\n  }\n\n  void Trigger(float hz, float vel) { kick_.NoteOn(hz, vel); }\n\n  /* Voices ADD into the range, so the caller owns clearing the block.\n   * That is the same contract the TypeScript uses, and it is what lets\n   * several voices share one buffer without a mix pass. */\n  void operator()(float* l, float* r, int from, int to) {\n    kick_.Process(l, r, from, to);\n  }\n\n  bool Active() const { return kick_.Active(); }\n\n private:\n  bellows::Kick kick_;\n};\n\n}  // namespace onekick\n";

export const onekick_ino: string = "/*\n * 01_OneKick: the minimum bellows program.\n *\n * One kick drum retriggering twice a second through the Teensy Audio\n * Library. Everything that makes a sound lives in onekick.h; this file is\n * only the board glue, which is the split the library is designed for.\n *\n * MEASURED COST, Cortex-M7, arm-none-eabi-g++ 11.3, -Os, --gc-sections,\n * library only (no Arduino core, no audio library):\n *\n *     flash 3776 B    RAM 1100 B\n *\n * For scale: the same kick reached by string id through a five-engine\n * registry costs 30296 B of flash and 30828 B of RAM. That is the entire\n * argument for how this library is put together.\n *\n * WIRING (Teensy 4.x plus the Audio Shield)\n *   Teensy 4.0/4.1 with a Rev D audio shield, headphones in the jack.\n *   Nothing else is required.\n *\n * PORTING\n *   On a Daisy Seed, replace the AudioStream plumbing with:\n *     #include \"bellows/platform/daisy.h\"\n *     bellows::DaisyAudio<onekick::Voice>::Start(hw, voice);\n *   The Voice class itself does not change. That port is done and built in\n *   examples/daisy_onekick, which includes this folder's onekick.h rather\n *   than copying it, so the claim is checked by the compiler.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"onekick.h\"\n\nstatic onekick::Voice voice;\n\n/* The adapter is the only virtual call in the whole program: the audio\n * library dispatches update() through AudioStream's vtable 344 times a\n * second. Nothing below it is virtual. */\nstatic bellows::BellowsAudioStream<onekick::Voice> node(voice);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n\n  /* Take the rate from the audio library rather than writing 44100 by\n   * hand: the SAI clock does not land exactly there, and every envelope\n   * coefficient in the voice is derived from this number. */\n  voice.Init(bellows::TeensySampleRate());\n  /* AudioMemory LAST, and this ordering is load bearing.\n   *\n   * BellowsAudioStream::update() returns early only while allocate() is\n   * null, which is to say only until AudioMemory() runs. After that the\n   * audio interrupt renders whatever it is pointed at, so anything\n   * initialised below this line can be rendered before it is ready. A\n   * delay line that has not been given its buffer reads through a null\n   * pointer, which on an IMXRT1062 is executable memory rather than a\n   * trap page. */\n  AudioMemory(12);\n  codec.enable();\n  codec.volume(0.6f);\n}\n\nvoid loop() {\n  voice.Trigger(50.0f, 0.9f);\n  delay(500);\n}\n";

export const drummachine_h: string = "/* Shared logic for the 02_DrumMachine example.\n *\n * Three drum voices behind a compile-time Bank, each pad driven by its own\n * euclidean pattern. This is the example that shows what replaces the\n * registry: pads are selected by a runtime integer, exactly as they would\n * be by string id in the TypeScript, but Bank resolves that integer\n * through a chain of compile-time-generated compares, so the linker still\n * sees three concrete types and can drop anything they do not reach.\n *\n * Euclidean rhythms are Bjorklund's algorithm, the same one in\n * src/seq/euclid.ts: spread k pulses as evenly as possible over n steps.\n * E(3,8) is the tresillo, E(5,8) the cinquillo, E(2,5) a common clave\n * fragment. The C++ Euclid stores the pattern as a bitmask rather than an\n * array of bools, so a 16 step pattern is two bytes plus a cursor.\n *\n * MEASURED COST, Cortex-M7, -Os, --gc-sections: see the report row for\n * p5_e2_drummachine. The kit is dominated by Snare and Hat, which use\n * BlepOsc and therefore pull in the band-limited step tables; the kick on\n * its own is 3760 B. */\n#pragma once\n\n#include \"bellows/bank.h\"\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/drums.h\"\n#include \"bellows/seq/euclid.h\"\n\nnamespace drummachine {\n\n/* Pad indices into the bank. Declaration order is the dispatch order. */\nenum Pad { kKick = 0, kSnare = 1, kHat = 2, kPadCount = 3 };\n\nclass Machine {\n public:\n  void Init(float sample_rate, unsigned bpm) {\n    rng_.Init(\"drummachine\");\n    sr_ = sample_rate;\n    SetTempo(bpm);\n\n    kit_.head.Init(sample_rate);                 /* Kick  */\n    kit_.tail.head.Init(sample_rate, &rng_);     /* Snare, needs noise */\n    kit_.tail.tail.head.Init(sample_rate);       /* Hat   */\n\n    /* Three patterns that lock together over 16 steps. The kick lands on\n     * a 5-in-16 euclidean spread, the snare answers on the backbeat, and\n     * the hat fills with 11 of 16 rotated by 1 so it never doubles the\n     * kick's downbeat. */\n    pattern_[kKick].Generate(5, 16);\n    pattern_[kSnare].Generate(4, 16, 4);\n    pattern_[kHat].Generate(11, 16, 1);\n\n    /* Tuning per pad, in Hz. Drum engines tune from the noteOn frequency,\n     * so a kit is playable up and down the keyboard. */\n    hz_[kKick] = 50.0f;\n    hz_[kSnare] = 190.0f;\n    hz_[kHat] = 330.0f;\n    vel_[kKick] = 0.95f;\n    vel_[kSnare] = 0.8f;\n    vel_[kHat] = 0.5f;\n  }\n\n  void SetTempo(unsigned bpm) {\n    /* Sixteenth notes: four steps per beat. */\n    float steps_per_sec = (static_cast<float>(bpm) / 60.0f) * 4.0f;\n    samples_per_step_ = static_cast<int>(sr_ / steps_per_sec + 0.5f);\n    if (samples_per_step_ < 1) samples_per_step_ = 1;\n  }\n\n  /* Advance the sequencer one step and fire whichever pads are on. */\n  void Step() {\n    for (int pad = 0; pad < kPadCount; ++pad) {\n      if (!pattern_[pad].Process()) continue;\n      const float f = hz_[pad];\n      const float v = vel_[pad];\n      /* Runtime index into a compile-time bank. No vtable, no table of\n       * function pointers, no string compare. */\n      kit_.With(pad, [f, v](auto& voice) { voice.NoteOn(f, v); });\n    }\n  }\n\n  /* Render one block, splitting it wherever a sequencer step falls so a\n   * hit lands on the exact sample rather than the block boundary. This is\n   * the same block-splitting idea the kernel uses. */\n  void operator()(float* l, float* r, int from, int to) {\n    int i = from;\n    while (i < to) {\n      if (countdown_ <= 0) {\n        Step();\n        countdown_ = samples_per_step_;\n      }\n      int span = to - i;\n      if (span > countdown_) span = countdown_;\n      kit_.ForEach([l, r, i, span](auto& voice) { voice.Process(l, r, i, i + span); });\n      i += span;\n      countdown_ -= span;\n    }\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::Bank<bellows::Kick, bellows::Snare, bellows::Hat> kit_;\n  bellows::Euclid<16> pattern_[kPadCount];\n  float hz_[kPadCount] = {0.0f, 0.0f, 0.0f};\n  float vel_[kPadCount] = {0.0f, 0.0f, 0.0f};\n  float sr_ = 48000.0f;\n  int samples_per_step_ = 1;\n  int countdown_ = 0;\n};\n\n}  // namespace drummachine\n";

export const drummachine_ino: string = "/*\n * 02_DrumMachine: a three piece kit driven by euclidean patterns.\n *\n * The sequencer runs inside the audio callback, not in loop(), which is\n * the important structural point. loop() on an Arduino is preempted by\n * every interrupt in the system and its timing is worth several\n * milliseconds of jitter; the audio block clock is exact. Machine::Step\n * is called from the render, and the render splits each block at the step\n * boundary so a hit lands on the sample it was scheduled for.\n *\n * All the logic is in drummachine.h so the size-report sketch\n * (test/sketches/p5_e2_drummachine.cpp) measures this same code.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack. Optional: a pot on A0 for tempo.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"drummachine.h\"\n\nstatic drummachine::Machine machine;\n\nstatic bellows::BellowsAudioStream<drummachine::Machine> node(machine);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nstatic const int kTempoPin = A0;\n\nvoid setup() {\n  codec.enable();\n  codec.volume(0.6f);\n  machine.Init(bellows::TeensySampleRate(), 120);\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(12);\n}\n\nvoid loop() {\n  /* Tempo is the one thing safe to change from loop(): it only affects\n   * how many samples the next step waits, and a torn read costs at worst\n   * one step of the wrong length. Nothing here allocates or blocks. */\n  int raw = analogRead(kTempoPin);          /* 0..1023 */\n  unsigned bpm = 60u + (static_cast<unsigned>(raw) * 120u) / 1023u;  /* 60..180 */\n  machine.SetTempo(bpm);\n  delay(50);\n}\n";

export const polysynth_h: string = "/* Shared logic for the 03_PolySynth example.\n *\n * Eight virtual-analog voices in a VoicePool with an LFO sweeping the\n * filter cutoff. VoicePool is a plain array of Va with the steal order\n * from src/core/voicepool.ts: a free voice first, then the oldest\n * released one, then the oldest held one. Nothing allocates, and note\n * identity is an int the caller chooses, so NoteOff finds its voice\n * without a search structure.\n *\n * The sweep is applied per block rather than per sample, which is the\n * same rate the TypeScript kernel steps a param ramp at. Filter cutoff is\n * a control signal; recomputing it 375 times a second at 128 frames is\n * far above anything audible in the movement and costs one SetParams per\n * voice per block instead of one per sample.\n *\n * Va is the expensive engine in this library (about 28.5 KB) because its\n * oscillators are band-limited and pull in the BLEP residual tables. That\n * is a fixed cost paid once, not per voice: eight voices cost eight times\n * the RAM but the same flash as one. */\n#pragma once\n\n#include \"bellows/config.h\"\n#include \"bellows/core/prng.h\"\n#include \"bellows/dsp/lfo.h\"\n#include \"bellows/engines/va.h\"\n#include \"bellows/voicepool.h\"\n\nnamespace polysynth {\n\ninline constexpr int kPoly = 8;\n\nclass Synth {\n public:\n  void Init(float sample_rate) {\n    rng_.Init(\"polysynth\");\n\n    /* Defaults match va.ts, so this is the browser patch until changed. */\n    bellows::Va::Params p;\n    p.shape = 0.35f;        /* between saw and square */\n    p.detune = 9.0f;        /* cents between the two oscillators */\n    p.sub = 0.25f;\n    p.resonance = 0.55f;    /* enough to hear the sweep sing */\n    p.env_amount = 0.0f;    /* the LFO drives cutoff here, not the envelope */\n    p.attack = 0.01f;\n    p.decay = 0.25f;\n    p.sustain = 0.7f;\n    p.release = 0.35f;\n    base_ = p;\n\n    for (int i = 0; i < kPoly; ++i) pool_.at(i).Init(sample_rate, &rng_, base_);\n\n    /* A slow triangle so the sweep moves in both directions evenly. */\n    sweep_.Init(sample_rate, &rng_);\n    sweep_.SetShape(bellows::LfoShape::kTriangle);\n    sweep_.SetFreq(0.12f);\n  }\n\n  void NoteOn(int note_id, float hz, float vel) { pool_.NoteOn(note_id, hz, vel, frame_); }\n  void NoteOff(int note_id) { pool_.NoteOff(note_id); }\n\n  int ActiveCount() { return pool_.ActiveCount(); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    /* One LFO sample per block drives the whole sweep. */\n    float lfo = sweep_.Process();                 /* -1 .. 1 */\n    float norm = 0.5f * (lfo + 1.0f);             /*  0 .. 1 */\n\n    /* Sweep exponentially, because pitch and filter cutoff are both\n     * perceived in octaves: 200 Hz to 200 * 2^5.5 which is about 9 kHz. */\n    float cutoff = 200.0f * bellows::fm::Exp2(norm * 5.5f);\n\n    bellows::Va::Params p = base_;\n    p.cutoff = bellows::Clamp(cutoff, 40.0f, 16000.0f);\n    for (int i = 0; i < kPoly; ++i) pool_.at(i).SetParams(p);\n\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::VoicePool<bellows::Va, kPoly> pool_;\n  bellows::Lfo sweep_;\n  bellows::Va::Params base_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace polysynth\n";

export const polysynth_ino: string = "/*\n * 03_PolySynth: eight voice VA polysynth with a swept filter.\n *\n * Holds a chord and lets the LFO walk the cutoff across it, so the\n * resonance is audible without any playing. Swap the arpeggio in loop()\n * for MIDI input and this becomes example 05.\n *\n * Note ids. VoicePool identifies a sounding note by an integer the caller\n * picks, and NoteOff(id) releases whichever voice is holding it. Using\n * the MIDI note number is the obvious choice and is what example 05 does.\n * Here the chord degrees double as ids.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"polysynth.h\"\n\nstatic polysynth::Synth synth;\n\nstatic bellows::BellowsAudioStream<polysynth::Synth> node(synth);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\n/* An A minor 9 spread over two octaves, as MIDI note numbers. */\nstatic const int kChord[] = {45, 52, 57, 60, 64, 67, 71, 76};\nstatic const int kChordSize = sizeof(kChord) / sizeof(kChord[0]);\n\n/* Equal-tempered MIDI to Hz. Example 04 replaces this one line with the\n * tuning layer, which is the point of that example. */\nstatic float MidiToHz(int note) {\n  return 440.0f * powf(2.0f, (static_cast<float>(note) - 69.0f) / 12.0f);\n}\n\nvoid setup() {\n  codec.enable();\n  codec.volume(0.6f);\n  synth.Init(bellows::TeensySampleRate());\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(16);\n}\n\nvoid loop() {\n  for (int i = 0; i < kChordSize; ++i) {\n    synth.NoteOn(kChord[i], MidiToHz(kChord[i]), 0.7f);\n    delay(180);\n  }\n  delay(2500);\n  for (int i = 0; i < kChordSize; ++i) synth.NoteOff(kChord[i]);\n  delay(1500);\n}\n";

export const scalestuning_h: string = "/* Shared logic for the 04_ScalesAndTuning example.\n *\n * This is the example that explains why the library exists. Almost every\n * embedded audio library hands you oscillators and filters and then\n * assumes twelve equal semitones per octave, usually by hard-coding\n * 440 * 2^((n - 69) / 12) somewhere in a note handler. Here pitch is not\n * a formula, it is a layer: a Scale says which degrees of a key are in\n * play, and a Tuning says what frequency each degree actually is. The\n * phrase below is written once, as scale degrees, and played in two\n * different divisions of the octave without changing a note of it.\n *\n * THE ONE THING TO UNDERSTAND HERE\n *\n * An interval table is expressed in steps of the tuning it is meant for,\n * not in semitones. src/theory/tuning.ts says so directly: \"intervals\n * lists tuning steps above the root, e.g. [0, 2, 4, 5, 7, 9, 11] for\n * major in edo(12)\". In 12-EDO a step is a semitone and the two readings\n * happen to coincide, which is why the distinction is easy to miss.\n *\n * They stop coinciding immediately in 19-EDO. A whole tone there is 3\n * steps and a diatonic semitone is 2, so dorian is not [0,2,3,5,7,9,10]\n * but [0,3,5,8,11,14,16]. Feed the semitone table to a 19-EDO tuning and\n * every interval comes out too small: degree 2 would be 189 cents, a\n * whole tone, where the scale wants a 316 cent minor third. The octave\n * would still be right, because degrees wrap by the tuning's period, so\n * the result sounds plausibly in tune and is completely wrong. That is\n * the classic microtonal bug and it is worth seeing named.\n *\n * So bellows::Scale, whose tables are the 12-EDO ones from scales.ts,\n * supplies the intervals for the 12-EDO pass, and the 19-EDO pass uses an\n * explicit table restated in 19-EDO steps.\n *\n * WHY 19-EDO IS WORTH HEARING\n *\n * Its major third is 6 steps, 378.95 cents, about 7 cents flat of a pure\n * 5:4 at 386.31. The 12-EDO major third is 400 cents, about 14 cents\n * sharp. So 19-EDO triads beat about half as fast and noticeably calmer.\n * The price is a fifth of 11 steps, 694.74 cents, about 7 cents flat of\n * a pure 701.96, and a chromatic scale with a genuinely different shape:\n * a sharp and its enharmonic flat are no longer the same pitch.\n *\n * Nothing here allocates and none of it touches an audio buffer: theory\n * is a pure layer over integers and floats, as in the TypeScript. */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/pluck.h\"\n#include \"bellows/theory/scales.h\"\n#include \"bellows/theory/tuning.h\"\n\nnamespace scalestuning {\n\n/* Degrees of the current scale, not note numbers. Values past the scale\n * length wrap and transpose by one period, so this spans two octaves and\n * is meaningful in any tuning. */\ninline constexpr int kPhrase[] = {0, 2, 4, 6, 7, 6, 4, 2, 0, 4, 7, 11, 7, 4, 2, 0};\ninline constexpr int kPhraseLen = static_cast<int>(sizeof(kPhrase) / sizeof(kPhrase[0]));\n\n/* Dorian restated in 19-EDO steps: W H W W W H W, with W = 3 and H = 2.\n * Compare bellows::kScaleDorian, which is the same mode in semitones. */\ninline constexpr uint8_t kDorian19[] = {0, 3, 5, 8, 11, 14, 16};\ninline constexpr int kDorian19Len = 7;\n\nusing Tuning19 = bellows::Tuning<19>;\n\nclass Player {\n public:\n  void Init(float sample_rate, unsigned bpm) {\n    rng_.Init(\"scalestuning\");\n    sr_ = sample_rate;\n    SetTempo(bpm);\n\n    bellows::Pluck<>::Params p;\n    p.damp = 0.3f;       /* rings long enough to judge the intonation */\n    p.pick_pos = 0.24f;\n    p.decay = 3.0f;\n    pluck_.Init(sample_rate, &rng_, p);\n\n    /* D dorian, reached by enum so no scale-name strings are linked in. */\n    scale_.Init(62, bellows::kScaleDorian);\n\n    /* Both tunings anchor A4 = 440 at index 69, so what you hear between\n     * the two passes is the tuning and not a transposition. */\n    edo12_.InitEdo(12, 440.0f, 69);\n    edo19_.InitEdo(19, 440.0f, 69);\n  }\n\n  void SetTempo(unsigned bpm) {\n    float notes_per_sec = (static_cast<float>(bpm) / 60.0f) * 2.0f;  /* eighths */\n    samples_per_note_ = static_cast<int>(sr_ / notes_per_sec + 0.5f);\n    if (samples_per_note_ < 1) samples_per_note_ = 1;\n  }\n\n  void UseNineteen(bool on) { nineteen_ = on; }\n  bool Nineteen() const { return nineteen_; }\n  int Position() const { return step_; }\n\n  /* Frequency of one degree in whichever tuning is selected.\n   *\n   * The root index differs between the two because a tuning index is a\n   * step of that tuning, not a MIDI note. D4 is index 62 in 12-EDO. The\n   * same note in 19-EDO is index 58, because A4 is index 69 in both and\n   * D sits a fifth below A, which is 11 steps of 19-EDO. */\n  float DegreeHz(int degree) const {\n    if (nineteen_) {\n      return bellows::DegreeFreq(edo19_, 58, kDorian19, kDorian19Len, degree);\n    }\n    return bellows::DegreeFreq(edo12_, 62, scale_.Intervals(), scale_.Length(), degree);\n  }\n\n  void Step() {\n    pluck_.NoteOn(DegreeHz(kPhrase[step_]), 0.85f);\n    if (++step_ >= kPhraseLen) {\n      step_ = 0;\n      nineteen_ = !nineteen_;  /* repeat the phrase in the other tuning */\n    }\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    int i = from;\n    while (i < to) {\n      if (countdown_ <= 0) {\n        Step();\n        countdown_ = samples_per_note_;\n      }\n      int span = to - i;\n      if (span > countdown_) span = countdown_;\n      pluck_.Process(l, r, i, i + span);\n      i += span;\n      countdown_ -= span;\n    }\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::Pluck<> pluck_;\n  bellows::Scale scale_;\n  bellows::Tuning12 edo12_;\n  Tuning19 edo19_;\n  float sr_ = 48000.0f;\n  int samples_per_note_ = 1;\n  int countdown_ = 0;\n  int step_ = 0;\n  bool nineteen_ = false;\n};\n\n}  // namespace scalestuning\n";

export const scalestuning_ino: string = "/*\n * 04_ScalesAndTuning: one phrase, two divisions of the octave.\n *\n * Plays a sixteen note phrase in D dorian, first in ordinary 12-EDO and\n * then in 19-EDO, alternating forever. The phrase is stored as scale\n * degrees, so nothing about it changes between the two passes: only the\n * tuning and the interval table do.\n *\n * WHAT TO LISTEN FOR\n *   The thirds. 19-EDO's minor third is 315.8 cents against a pure 6:5 of\n *   315.64, so it is very nearly just and sounds settled where the 12-EDO\n *   minor third at 300 cents sounds tense. The fifths go the other way:\n *   19-EDO's is 7 cents flat and slightly restless. The octaves are\n *   identical, exactly 2:1 in both.\n *\n *   The LED on pin 13 is lit for the 19-EDO pass, so you can tell the two\n *   apart without counting.\n *\n * WHY THIS EXAMPLE EXISTS\n *   Retuning normally means rewriting a note handler. Here it is a\n *   different Tuning object and a scale table restated in that tuning's\n *   steps. Read scalestuning.h before changing anything: it explains why\n *   the 19-EDO scale is [0,3,5,8,11,14,16] and not the semitone table,\n *   which is the one mistake this subject reliably produces.\n *\n * TRY NEXT\n *   Tuning::InitJi takes a list of ratios, so a 5-limit just intonation\n *   scale is one call. Tuning::InitCents takes a cents table, which is\n *   what a Scala .scl file is. Neither needs anything else to change.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"scalestuning.h\"\n\nstatic scalestuning::Player player;\n\nstatic bellows::BellowsAudioStream<scalestuning::Player> node(player);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  codec.enable();\n  codec.volume(0.6f);\n  pinMode(LED_BUILTIN, OUTPUT);\n  player.Init(bellows::TeensySampleRate(), 96);\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(12);\n}\n\nvoid loop() {\n  digitalWrite(LED_BUILTIN, player.Nineteen() ? HIGH : LOW);\n  delay(20);\n}\n";

export const audioshield_h: string = "/* Shared patch for the output examples 10 through 14.\n *\n * A plucked chord arriving one note at a time. It exists to give the\n * output examples something with real dynamic range to push through a\n * converter: a kick tells you the wiring works, a decaying string tells\n * you whether the noise floor and the headroom are where you think.\n *\n * WHY THIS FILE IS FULL OF BOARD CONDITIONALS\n *\n * A Karplus-Strong string IS its delay line, and the line has to be long\n * enough for the lowest note it will ever play: at 48 kHz a 20 Hz floor is\n * 2404 samples, which is 9.6 KB of float per voice. Four voices is 38 KB,\n * and a Teensy 3.2 has 64 KB in total with the audio library already in\n * it. Measured, before this file knew what board it was on: `.bss' will\n * not fit in region `RAM', overflowed by 61540 bytes.\n *\n * So the floor is a template parameter, and choosing it is the single most\n * consequential decision in an embedded bellows patch. Raising it from\n * 20 Hz to 100 Hz costs five times less RAM per voice and costs nothing\n * else, as long as no note goes below it. The chord here bottoms out at\n * 110 Hz, so 100 is free on the small boards.\n *\n * This is not a workaround, it is the design: every buffer-owning class in\n * the library takes its size at compile time so the sketch decides, and\n * the library never allocates.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/pluck.h\"\n\nnamespace audioshield {\n\n/* Lowest note the strings must be able to play, and how many of them.\n *\n *   Teensy 4.x     512 KB    the full range, four voices, nothing to think about\n *   Teensy 3.5/3.6 256 KB    the same, with room to spare\n *   Teensy 3.2      64 KB    a 100 Hz floor and two voices fits with room\n *   Teensy LC        8 KB    does not fit at all, see examples/README.md\n */\n#if !defined(AUDIOSHIELD_MIN_HZ)\n#if defined(__IMXRT1062__) || defined(__MK64FX512__) || defined(__MK66FX1M0__)\n#define AUDIOSHIELD_MIN_HZ 20\n#define AUDIOSHIELD_VOICES 4\n#else\n#define AUDIOSHIELD_MIN_HZ 100\n#define AUDIOSHIELD_VOICES 2\n#endif\n#endif\n\n/* Overridable so the size-report sketch can pin a configuration. Without\n * that, the freestanding build defines none of the board macros, silently\n * takes the small branch, and the reported cost would be for a patch no\n * Teensy 4.1 sketch ever compiles. */\ninline constexpr int kMinHz = AUDIOSHIELD_MIN_HZ;\ninline constexpr int kVoices = AUDIOSHIELD_VOICES;\n\nusing String = bellows::Pluck<kMinHz>;\n\n/* A minor 7th, which spreads across the octave without any note masking\n * another, so a fault in one voice is audible rather than hidden. The\n * lowest note is 110 Hz, comfortably above the 100 Hz floor above; drop\n * a note below kMinHz and Pluck clamps it, which sounds like the chord\n * silently changing shape. */\ninline constexpr float kChordHz[4] = {110.0f, 130.81f, 164.81f, 196.0f};\n\nclass Patch {\n public:\n  void Init(float sample_rate) {\n    /* One seeded stream per voice, forked from a named root. Two boards\n     * running this sketch produce the same excitation burst in the same\n     * voice on the same note, which is what makes \"does this board sound\n     * different\" a question with an answer. */\n    rng_.Init(\"audioshield\");\n    String::Params p;\n    p.damp = 0.3f;      /* a touch brighter than the 0.35 default */\n    p.decay = 3.0f;     /* and ringing longer, so the tail is audible */\n    p.pick_pos = 0.22f;\n    for (int i = 0; i < kVoices; ++i) {\n      voice_rng_[i].Init(rng_.NextU32());\n      pluck_[i].Init(sample_rate, &voice_rng_[i], p);\n    }\n  }\n\n  /* Round robin, so a fast pattern overlaps its own tails instead of\n   * cutting them. */\n  void Strike(int index, float vel) {\n    const int i = index % kVoices;\n    pluck_[i].NoteOn(kChordHz[index % 4], vel);\n  }\n\n  /* Voices ADD into the range, so the caller owns clearing the block. */\n  void operator()(float* l, float* r, int from, int to) {\n    for (int i = 0; i < kVoices; ++i) pluck_[i].Process(l, r, from, to);\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::Rng voice_rng_[kVoices];\n  String pluck_[kVoices];\n};\n\n}  // namespace audioshield\n";

export const audioshield_ino: string = "/*\n * 10_AudioShield: bellows through the Teensy Audio Shield (SGTL5000).\n *\n * The reference output path. If you own one shield and one Teensy this is\n * the sketch to start from, because the codec removes every variable the\n * other output examples have to argue about: it is a real 16 bit stereo\n * DAC with a headphone amplifier and a line output, so what you hear is\n * the library rather than the driver.\n *\n * BOARDS\n *   Builds for Teensy 3.2, 3.5, 3.6, 4.0, 4.1 and MicroMod. The shield\n *   comes in two revisions and they are not pin compatible with every\n *   board: Rev D is the 3.x shield, Rev C/D differ for Teensy 4.x. Buy the\n *   revision sold for your board and stack it; no wiring beyond that.\n *\n * WIRING\n *   Stack the shield. Headphones in the jack, or line out to a mixer.\n *   Nothing else. The shield takes I2S on the pins it takes and the audio\n *   library configures them; you do not choose them.\n *\n * WHAT IS VERIFIED\n *   That this builds and links as firmware for the boards listed above.\n *   NOTHING HERE HAS BEEN FLASHED TO A BOARD AND LISTENED TO. See\n *   examples/README.md, which says the same thing once rather than in\n *   every file, and docs/HANDOFF.md, which has said it since the port\n *   started. Assume the first bring-up finds something.\n *\n * THE ONE KNOB THAT MATTERS\n *   codec.volume() drives the headphone amplifier, not the DAC. Leave it\n *   near 0.5 and change the level in the patch instead: turning the\n *   headphone amp up to compensate for a quiet render amplifies the\n *   codec's noise floor along with the music.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"audioshield.h\"\n\nstatic audioshield::Patch patch;\nstatic bellows::BellowsAudioStream<audioshield::Patch> node(patch);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n\n  codec.enable();\n  codec.volume(0.5f);\n\n  /* Take the rate from the audio library rather than writing 44100: the\n   * SAI clock does not land exactly there, and every envelope coefficient\n   * in the patch is derived from this number. */\n  patch.Init(bellows::TeensySampleRate());\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(12);\n}\n\nvoid loop() {\n  static int n = 0;\n  patch.Strike(n++, 0.8f);\n  delay(400);\n}\n";

export const piezo_h: string = "/* Voicing a bellows patch for a piezo disc.\n *\n * A piezo disc is not a small speaker. It is a capacitor, around 10 to 20\n * nF for a 27 mm brass disc, glued to a metal plate with a sharp mechanical\n * resonance, and it moves almost no air anywhere else. Feeding it the same\n * signal you would send an 8 ohm cone wastes nearly all of the available\n * voltage swing on frequencies it cannot reproduce.\n *\n * There are four things that help, in order of how much:\n *\n * 1. DRIVE IT DIFFERENTIALLY. A logic pin swings 3.3 V. Two pins in\n *    antiphase across the disc swing 6.6 V, which is 6 dB, which is more\n *    than everything below put together. That part is in the .ino, because\n *    it is wiring rather than DSP: this header renders the signal and its\n *    inverse into the two channels.\n *\n * 2. THROW AWAY THE BASS. Not attenuate: remove. The disc's impedance is\n *    1 / (2*pi*f*C), so at 100 Hz a 15 nF disc is about a megaohm and\n *    essentially nothing flows. Every volt spent down there is a volt not\n *    available at 4 kHz, and since the limiter below works on peaks, bass\n *    the disc cannot reproduce still steals headroom from the part it can.\n *    Two poles of highpass, high.\n *\n * 3. BOOST WHERE IT RINGS. The disc has a strong resonance, usually\n *    somewhere between 2 and 6 kHz, and it is much louder there than\n *    anywhere else. Find yours (the .ino has a sweep mode) and put the\n *    bell on it.\n *\n * 4. LIMIT HARD. There is no headroom to protect: the swing is fixed by\n *    the supply and anything above it clips at the pin regardless. So the\n *    useful move is to raise the average level until it is just under the\n *    ceiling all the time, which is what a limiter with a low ceiling and\n *    a fast release does.\n *\n * What this cannot fix: a piezo has no bass, and no amount of processing\n * invents any. A bass line played through one is heard through its\n * harmonics, so patches for a piezo should be written an octave or two up\n * from where they would sit on a speaker.\n */\n#pragma once\n\n#include \"bellows/dsp/filters.h\"\n#include \"bellows/fx/dynamics.h\"\n#include \"bellows/fx/eq.h\"\n\nnamespace piezo {\n\n/* Defaults for a common 27 mm brass disc. Measure yours: the .ino's sweep\n * mode steps a tone across the band so you can hear which is loudest, and\n * that frequency is what belongs in resonance_hz. Mounting changes it, and\n * a disc glued to a box will be lower than a disc held in the air. */\nstruct Voicing {\n  /* Everything below here is thrown away. 1200 is conservative for a bare\n   * disc; a mounted one can usually go lower. */\n  float highpass_hz = 1200.0f;\n  /* The disc's mechanical resonance, and how hard to lean on it. */\n  float resonance_hz = 4000.0f;\n  float resonance_db = 8.0f;\n  float resonance_q = 1.2f;\n  /*\n   * Gain applied after the filtering and before the limiter.\n   *\n   * The chain above is subtractive: two cascaded highpasses throw away\n   * everything the disc cannot reproduce, and on a full-range patch that\n   * is most of the energy. Measured on 07_Workstation, whose kick is at\n   * 50 Hz and whose bass runs 110 to 262 Hz, the chain took RMS from\n   * -19.5 dBFS to -32.9, and the peak reached 0.658 against a ceiling of\n   * 0.944, so the limiter never engaged once and the disc saw a third of\n   * the swing it could have had.\n   *\n   * Point 4 at the top of this file says the useful move is to raise the\n   * average level until it is just under the ceiling all the time. This\n   * is the control that does it. 1.0 leaves the chain exactly as it was.\n   */\n  float drive = 1.0f;\n  /* Just under full scale. Not 0 dB: the pin clips hard and squarely, and\n   * the last fraction of a dB is not worth the sound of that. */\n  float ceiling_db = -0.5f;\n  float release = 0.02f;\n};\n\n/* Wraps any bellows render and voices its output for a disc. Render is a\n * template parameter for the same reason it is one in the platform\n * adapters: the call inlines and the linker still sees exactly which\n * engines the sketch reaches. */\ntemplate <class Render>\nclass Voiced {\n public:\n  explicit Voiced(Render& render) : render_(&render) {}\n\n  void Init(float sample_rate, const Voicing& v = Voicing()) {\n    v_ = v;\n    /* Two cascaded one-pole-pair highpasses rather than one, because a\n     * single 12 dB slope still leaves plenty of 400 Hz energy in the\n     * limiter's sidechain, and the limiter cannot tell that the disc will\n     * never reproduce it. 24 dB/octave costs four biquads and buys back\n     * real loudness. */\n    for (int i = 0; i < 2; ++i) {\n      for (int c = 0; c < 2; ++c) {\n        hp_[i][c].Init(sample_rate);\n        hp_[i][c].SetMode(bellows::SvfMode::kHp);\n        hp_[i][c].Set(v_.highpass_hz, 0.707f);\n      }\n    }\n    bell_.Init(sample_rate, bellows::SvfMode::kBell, v_.resonance_hz, v_.resonance_q);\n    bell_.Set(v_.resonance_hz, v_.resonance_db, v_.resonance_q, true);\n\n    bellows::Limiter<>::Params lp;\n    lp.ceiling_db = v_.ceiling_db;\n    lp.release = v_.release;\n    limiter_.Init(sample_rate, lp);\n  }\n\n  /* The bellows render signature, so this drops straight into\n   * BellowsAudioStream in place of the patch it wraps. */\n  void operator()(float* l, float* r, int from, int to) {\n    (*render_)(l, r, from, to);\n\n    for (int n = from; n < to; ++n) {\n      float x = 0.5f * (l[n] + r[n]);  /* one disc, so one signal */\n      for (int i = 0; i < 2; ++i) x = hp_[i][0].Process(x);\n      if (!bell_.Bypassed()) x = bell_.Process(0, x);\n      /* After the filtering, so it lifts only what the disc can use, and\n       * before the limiter, so the limiter is what controls the peaks. */\n      x *= v_.drive;\n      l[n] = x;\n      r[n] = x;\n    }\n\n    limiter_.Process(l, r, from, to);\n\n    /* The differential half of the trick. Left goes to one pin, right to\n     * the other, and the disc sits between them, so it sees twice the\n     * swing either pin can produce on its own. Wire it single-ended and\n     * you get the same sound 6 dB quieter, which still works. */\n    for (int n = from; n < to; ++n) r[n] = -l[n];\n  }\n\n private:\n  Render* render_;\n  Voicing v_;\n  bellows::Svf hp_[2][2];\n  bellows::EqBand bell_;\n  bellows::Limiter<> limiter_;\n};\n\n}  // namespace piezo\n";

export const piezo_ino: string = "/*\n * 15_Piezo: getting the most out of a piezo disc as a loudspeaker.\n *\n * A piezo disc costs about thirty cents, needs no amplifier, and is the\n * cheapest way to make a Teensy audible. It is also a capacitor with a\n * sharp resonance and no bass whatsoever, so the difference between a\n * patch that sounds like a wasp and one that sounds like an instrument is\n * almost entirely in how you drive it. piezo.h is that difference and has\n * the reasoning; this file is the wiring and the two modes.\n *\n * BOARDS\n *   Builds for Teensy 3.2, 3.5, 3.6, 4.0, 4.1 and MicroMod. Teensy 4.x\n *   uses MQS on pins 10 and 12; the 3.x boards use PWM on pins 6 and 9.\n *   Both are selected below by the board macros, so the sketch is the same\n *   either way.\n *\n * WIRING, AND THE ONE THING THAT MATTERS\n *\n *   Teensy 4.x:   pin 10 ---[ piezo disc ]--- pin 12\n *   Teensy 3.x:   pin  6 ---[ piezo disc ]--- pin  9\n *\n *   Across the two pins, NOT from one pin to ground. The sketch renders\n *   the signal on one channel and its exact inverse on the other, so the\n *   disc sees both pins swinging in opposite directions and gets twice\n *   the voltage: 6.6 V peak to peak instead of 3.3. That is 6 dB, free,\n *   and it is the single largest improvement available here.\n *\n *   To ground instead works and is 6 dB quieter. Nothing breaks.\n *\n *   No series resistor is needed for a disc this size, and no capacitor:\n *   a piezo is already a capacitor and passes no DC. Do not put one in\n *   series \"for safety\"; it makes the bass problem worse.\n *\n * A NOTE ON LOUDNESS\n *   The disc will be loud and thin. That is what the part is. If you want\n *   it louder still, glue it to something: a disc lying loose moves almost\n *   nothing, and the same disc on a biscuit tin lid or a stretched\n *   membrane is dramatically louder and drops its resonance, which you\n *   then want to re-measure with SWEEP mode below.\n *\n * TWO MODES\n *   SWEEP  steps a tone from 800 Hz to 8 kHz, a semitone at a time,\n *          printing each frequency. Listen for the loudest, and put that\n *          number in Voicing::resonance_hz. Takes about twenty seconds.\n *   PLAY   the plucked chord from the other output examples, voiced for\n *          the disc.\n *\n * WHAT IS VERIFIED\n *   That this builds and links for the boards listed above. Nothing here\n *   has been flashed to a board, and the piezo advice is engineering\n *   reasoning about a capacitive transducer rather than a measurement.\n *   See examples/README.md.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"../10_AudioShield/audioshield.h\"\n#include \"bellows/dsp/oscillators.h\"\n#include \"piezo.h\"\n\n/* Set to true to hunt for your disc's resonance, false to play. */\nstatic constexpr bool kSweep = false;\n\n/* One source, not two.\n *\n * The first version of this sketch had a node for the chord and a node for\n * the sweep and connected both to the output. The Teensy Audio Library\n * does not mix on a shared destination input: one input takes one\n * connection, and a second AudioConnection to the same port is not an\n * addition. Mixing needs an AudioMixer4, or, as here, one source that\n * knows which of its two generators is running. That also halves the\n * voicing chain, since there is now one of it rather than two.\n */\nstruct Source {\n  audioshield::Patch chord;\n  bellows::BlepOsc osc;\n  bool sweeping = false;\n\n  void Init(float sr) {\n    chord.Init(sr);\n    osc.Init(sr);\n    osc.SetShape(bellows::BlepShape::kSine);\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    if (sweeping) {\n      for (int n = from; n < to; ++n) {\n        const float s = 0.9f * osc.Process();\n        l[n] += s;\n        r[n] += s;\n      }\n    } else {\n      chord(l, r, from, to);\n    }\n  }\n};\n\nstatic Source source;\nstatic piezo::Voiced<Source> voiced(source);\nstatic bellows::BellowsAudioStream<piezo::Voiced<Source>> node(voiced);\n\n#if defined(__IMXRT1062__)\n/* MQS: Medium Quality Sound, pins 10 and 12, no external parts at all.\n * It is a sigma-delta output filtered by the disc itself, which for a\n * transducer that rolls off above its resonance is a better match than it\n * sounds. Teensy 4.x only. */\nstatic AudioOutputMQS out;\n#else\n/* PWM on pins 6 and 9. The audio library's own documentation asks for an\n * RC filter for a line output; driving a piezo you can usually omit it,\n * because the disc's own capacitance plus its rolloff does the filtering\n * and there is nothing downstream to offend. */\nstatic AudioOutputPWM out;\n#endif\n\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  const float sr = bellows::TeensySampleRate();\n\n  source.Init(sr);\n\n  piezo::Voicing v;\n  /* Measure yours with kSweep and change this one number. Everything else\n   * in Voicing is a reasonable default for a bare 27 mm disc. */\n  v.resonance_hz = 4000.0f;\n  voiced.Init(sr, v);\n\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(12);\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  if (kSweep) {\n    /* 800 Hz up to 8 kHz, a semitone at a time. */\n    source.sweeping = true;\n    for (int semi = 0; semi <= 40; ++semi) {\n      const float hz = 800.0f * powf(2.0f, semi / 12.0f);\n      source.osc.SetFreq(hz);\n      Serial.println(hz);\n      delay(400);\n    }\n    source.sweeping = false;\n    delay(1500);\n  } else {\n    static int n = 0;\n    source.chord.Strike(n++, 0.9f);\n    delay(400);\n  }\n}\n";

export const firststeps_ino: string = "/*\n * 06_FirstSteps: the four rungs below 01_OneKick.\n *\n * 01 is described as the smallest useful program, and it is, but it is\n * already an engine: Kick is an oscillator, two envelopes, a pitch sweep\n * and a saturator behind one NoteOn. If it does not make a sound on your\n * board there are half a dozen places to look.\n *\n * These four are the primitives it is made of, one at a time, each in its\n * own header:\n *\n *   tone.h      one oscillator. No note, no envelope. It just runs.\n *   envelope.h  the same oscillator, gated. A tone becomes a note.\n *   filter.h    a second envelope on a resonant ladder. A note becomes a\n *               sound, and this is 03_PolySynth without the voice pool.\n *   motion.h    two LFOs, on cutoff and on pitch. It stops sounding like a\n *               sample.\n *\n * The sketch plays each for four seconds and moves on, so one flash walks\n * the whole ladder. Which one you are hearing goes to Serial.\n *\n * All four are linked into this image at once, which is the point of the\n * Bank: dispatch is a runtime index through compile-time-generated\n * compares, so there is no vtable and no registry, and the linker still\n * sees four concrete types. See bellows/bank.h and the note in\n * docs/HANDOFF.md about why a string-keyed registry costs 30 KB.\n *\n * BOARDS\n *   All of them, including a Teensy LC. This is the cheapest example here\n *   and the only one with no delay line anywhere in it.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack.\n *\n * WHAT IS VERIFIED\n *   Each header compiles standalone, all four link as one image, and each\n *   was rendered offline and measured for level and pitch. Nothing here\n *   has been flashed to a board. See examples/README.md.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/bank.h\"\n#include \"bellows/platform/teensy.h\"\n\n#include \"envelope.h\"\n#include \"filter.h\"\n#include \"motion.h\"\n#include \"tone.h\"\n\n/* Declaration order is dispatch order, and it is the order of the ladder. */\nenum Step { kTone = 0, kEnvelope, kFilter, kMotion, kStepCount };\n\nstatic const char* kStepName[kStepCount] = {\n    \"1 tone     : one oscillator, no envelope\",\n    \"2 envelope : the same oscillator, gated\",\n    \"3 filter   : a resonant ladder with its own envelope\",\n    \"4 motion   : two LFOs, on cutoff and on pitch\",\n};\n\n/*\n * The Bank holds one of each and renders whichever index is selected.\n * A plain switch would work as well here; this is what the rest of the\n * library uses, and it is what 02_DrumMachine is demonstrating.\n */\nstatic bellows::Bank<firststeps::Tone, firststeps::Envelope, firststeps::Filter,\n                     firststeps::Motion>\n    steps;\n\nclass Ladder {\n public:\n  void Init(float sample_rate) {\n    steps.ForEach([sample_rate](auto& s) { s.Init(sample_rate); });\n  }\n  void Select(int i) { which_ = i; }\n  int Selected() const { return which_; }\n  void operator()(float* l, float* r, int from, int to) {\n    steps.With(which_, [l, r, from, to](auto& s) { s(l, r, from, to); });\n  }\n\n private:\n  int which_ = 0;\n};\n\nstatic Ladder ladder;\n\nstatic bellows::BellowsAudioStream<Ladder> node(ladder);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  Serial.begin(115200);\n  codec.enable();\n  codec.volume(0.5f);\n  ladder.Init(bellows::TeensySampleRate());\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(12);\n}\n\nvoid loop() {\n  for (int i = 0; i < kStepCount; ++i) {\n    ladder.Select(i);\n    Serial.println(kStepName[i]);\n    delay(4000);\n  }\n}\n";

export const tone_h: string = "/* Step 1 of the 06_FirstSteps example: a tone.\n *\n * The smallest thing in this library that makes a sound, and it is smaller\n * than 01_OneKick: one oscillator, written straight into the buffer. No\n * engine, no envelope, no filter, no note. It starts when the board starts\n * and it does not stop.\n *\n * The point of having a rung this low is that it separates two questions\n * that get tangled on a first bring-up. If this is silent, the problem is\n * wiring, the codec, or the sample rate. If this is audible and something\n * else is not, the problem is in the program. Nothing here can be wrong\n * except the pitch.\n *\n * BlepOsc is band limited, which is the one thing that is not simple about\n * it. A saw built the obvious way, a counter ramping and wrapping, folds\n * every harmonic above Nyquist back down into the audible band as an\n * inharmonic whine that gets worse as you play higher. This one subtracts\n * a tabulated Kaiser-windowed sinc at each discontinuity instead, measured\n * at -85 dB or better through the musical range. That is why one\n * oscillator is 8552 B of flash rather than 200: the table is most of it,\n * and it is paid once no matter how many oscillators read it.\n *\n * Voices ADD into the buffer, so this one does too, and the caller clears\n * the block. That contract is the same all the way up the library.\n *\n * All four rungs share one namespace, `firststeps`, rather than having one\n * each. That is the convention the other examples follow, and here it is\n * also load bearing: this file was `namespace tone` first and it does not\n * compile, because the Arduino core declares `void tone(uint8_t pin,\n * uint16_t frequency, uint32_t duration)` and a namespace cannot share a\n * name with a function. Nothing on the host could see it, since a host\n * probe never includes Arduino.h. The board matrix caught it, which is the\n * argument for the matrix building real firmware rather than headers. */\n#pragma once\n\n#include \"bellows/dsp/oscillators.h\"\n\nnamespace firststeps {\n\nclass Tone {\n public:\n  struct Params {\n    /* A3. Low enough to hear the body of the waveform, high enough that a\n     * small speaker or a piezo will pass it. */\n    float freq = 220.0f;\n    float level = 0.25f;\n  };\n\n  void Init(float sample_rate) {\n    Params p;\n    p.freq = 220.0f;\n    p.level = 0.25f;\n    Init(sample_rate, p);\n  }\n\n  void Init(float sample_rate, const Params& p) {\n    p_ = p;\n    osc_.Init(sample_rate);\n    osc_.SetShape(bellows::BlepShape::kSaw);\n    osc_.SetFreq(p_.freq);\n  }\n\n  void SetParams(const Params& p) {\n    p_ = p;\n    osc_.SetFreq(p_.freq);\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    for (int i = from; i < to; ++i) {\n      const float s = osc_.Process() * p_.level;\n      l[i] += s;\n      r[i] += s;\n    }\n  }\n\n private:\n  bellows::BlepOsc osc_;\n  Params p_;\n};\n\n}  // namespace firststeps\n";

export const fs_envelope_h: string = "/* Step 2 of the 06_FirstSteps example: a note.\n *\n * The same oscillator as step 1 with an envelope on its amplitude, and a\n * counter that retriggers it. That is the whole difference between a tone\n * and a note: something has to decide when it starts and how it stops.\n *\n * ADSR is four numbers and only one of them is a shape rather than a time.\n * Attack, decay and release are how long; sustain is how loud it sits\n * while a key is held, from 0 to 1. Set sustain to 0 and decay becomes the\n * whole of the note, which is how every percussive sound in this library\n * is built, including the kick in 01_OneKick.\n *\n * The curves are exponential, not linear, because hearing is. The\n * constants that set them are in dsp/envelopes.h and they are chosen so\n * the attack crosses 1.0 at exactly the attack time (ln 3) and decay and\n * release cover 99 percent of their span in the time you asked for\n * (ln 100). Without that a \"0.5 second decay\" means whatever the\n * implementation felt like.\n *\n * Gate length is deliberately a separate number from the envelope. The\n * note is released partway through the step, so you can hear the release\n * as its own stage rather than as the start of the next note. */\n#pragma once\n\n#include \"bellows/dsp/envelopes.h\"\n#include \"bellows/dsp/oscillators.h\"\n\nnamespace firststeps {\n\nclass Envelope {\n public:\n  struct Params {\n    float freq = 220.0f;\n    float attack = 0.005f;\n    float decay = 0.12f;\n    float sustain = 0.55f;\n    float release = 0.25f;\n    /* Fraction of the step the note is held for, before the release. */\n    float gate = 0.5f;\n    float level = 0.3f;\n  };\n\n  void Init(float sample_rate) {\n    Params p;\n    p.freq = 220.0f;\n    p.attack = 0.005f;\n    p.decay = 0.12f;\n    p.sustain = 0.55f;\n    p.release = 0.25f;\n    p.gate = 0.5f;\n    p.level = 0.3f;\n    Init(sample_rate, p);\n  }\n\n  void Init(float sample_rate, const Params& p) {\n    sr_ = sample_rate;\n    osc_.Init(sample_rate);\n    osc_.SetShape(bellows::BlepShape::kSaw);\n    env_.Init(sample_rate);\n    SetParams(p);\n    SetTempo(120);\n  }\n\n  void SetParams(const Params& p) {\n    p_ = p;\n    osc_.SetFreq(p_.freq);\n    env_.Set(p_.attack, p_.decay, p_.sustain, p_.release);\n  }\n\n  /* One note per beat. */\n  void SetTempo(unsigned bpm) {\n    /* Clamped before the divide: bpm 0 makes an infinity and casting that\n     * to int is undefined. */\n    if (bpm < 20u) bpm = 20u;\n    if (bpm > 400u) bpm = 400u;\n    float per_sec = static_cast<float>(bpm) / 60.0f;\n    samples_per_step_ = static_cast<int>(sr_ / per_sec + 0.5f);\n    if (samples_per_step_ < 2) samples_per_step_ = 2;\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    for (int i = from; i < to; ++i) {\n      if (pos_ == 0) env_.Trigger();\n      /* Release partway through, so the release stage is audible on its\n       * own rather than being cut off by the next attack. */\n      if (pos_ == static_cast<int>(static_cast<float>(samples_per_step_) * p_.gate)) {\n        env_.Release();\n      }\n      const float s = osc_.Process() * env_.Process() * p_.level;\n      l[i] += s;\n      r[i] += s;\n      if (++pos_ >= samples_per_step_) pos_ = 0;\n    }\n  }\n\n private:\n  bellows::BlepOsc osc_;\n  bellows::Adsr env_;\n  Params p_;\n  float sr_ = 48000.0f;\n  int samples_per_step_ = 1;\n  int pos_ = 0;\n};\n\n}  // namespace firststeps\n";

export const fs_filter_h: string = "/* Step 3 of the 06_FirstSteps example: a sound.\n *\n * Step 2 plus a filter, and a second envelope to move it. This is the rung\n * where it stops being a test tone: a saw through a resonant lowpass whose\n * cutoff falls as the note decays is most of what a subtractive synth is,\n * and 03_PolySynth is this with a voice pool around it.\n *\n * Two envelopes rather than one, because they are doing different jobs.\n * The amplitude envelope says how loud, the filter envelope says how\n * bright, and they almost never want the same times: a plucked sound is a\n * slow amplitude decay under a fast brightness decay. Sharing one is the\n * commonest reason a patch sounds like a toy.\n *\n * The ladder is the Moog topology: four one-pole stages with a tanh in\n * each and a feedback path whose gain is the resonance. Its cutoff is set\n * against 2x the sample rate, which is deliberate and documented in\n * dsp/filters.h; it is not a bug and audit 2 refuted it twice.\n *\n * Resonance is the knob to turn. Past about 0.9 the feedback loop starts\n * to sustain itself and the filter sings its own pitch, which is a synth\n * sound rather than a fault. */\n#pragma once\n\n#include \"bellows/dsp/envelopes.h\"\n#include \"bellows/dsp/filters.h\"\n#include \"bellows/dsp/oscillators.h\"\n\nnamespace firststeps {\n\nclass Filter {\n public:\n  struct Params {\n    float freq = 110.0f;\n    /* Where the filter opens to at the peak of the note. */\n    float cutoff = 2600.0f;\n    /* Where it falls back to. The sweep between the two is the sound. */\n    float cutoff_floor = 180.0f;\n    float resonance = 0.72f;\n    float decay = 0.45f;\n    float filter_decay = 0.22f;\n    float level = 0.32f;\n  };\n\n  void Init(float sample_rate) {\n    Params p;\n    p.freq = 110.0f;\n    p.cutoff = 2600.0f;\n    p.cutoff_floor = 180.0f;\n    p.resonance = 0.72f;\n    p.decay = 0.45f;\n    p.filter_decay = 0.22f;\n    p.level = 0.32f;\n    Init(sample_rate, p);\n  }\n\n  void Init(float sample_rate, const Params& p) {\n    sr_ = sample_rate;\n    osc_.Init(sample_rate);\n    osc_.SetShape(bellows::BlepShape::kSaw);\n    amp_.Init(sample_rate);\n    filt_.Init(sample_rate);\n    ladder_.Init(sample_rate);\n    SetParams(p);\n    SetTempo(120);\n  }\n\n  void SetParams(const Params& p) {\n    p_ = p;\n    osc_.SetFreq(p_.freq);\n    /* Sustain 0 on both, so decay is the whole of the note and there is\n     * nothing to hold. */\n    amp_.Set(0.004f, p_.decay, 0.0f, 0.05f);\n    filt_.Set(0.002f, p_.filter_decay, 0.0f, 0.05f);\n  }\n\n  void SetTempo(unsigned bpm) {\n    /* Clamped before the divide: bpm 0 makes an infinity and casting that\n     * to int is undefined. */\n    if (bpm < 20u) bpm = 20u;\n    if (bpm > 400u) bpm = 400u;\n    float per_sec = (static_cast<float>(bpm) / 60.0f) * 2.0f; /* eighths */\n    samples_per_step_ = static_cast<int>(sr_ / per_sec + 0.5f);\n    if (samples_per_step_ < 2) samples_per_step_ = 2;\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    for (int i = from; i < to; ++i) {\n      if (pos_ == 0) {\n        amp_.Trigger();\n        filt_.Trigger();\n      }\n      /* One filter update per sample. It is a control signal, so per block\n       * would do and is what 03_PolySynth does; per sample here because\n       * the sweep is short enough to hear the steps at 128 frames. */\n      const float e = filt_.Process();\n      const float span = p_.cutoff - p_.cutoff_floor;\n      ladder_.Set(p_.cutoff_floor + span * e, p_.resonance);\n      const float s = ladder_.Process(osc_.Process()) * amp_.Process() * p_.level;\n      l[i] += s;\n      r[i] += s;\n      if (++pos_ >= samples_per_step_) pos_ = 0;\n    }\n  }\n\n private:\n  bellows::BlepOsc osc_;\n  bellows::Adsr amp_;\n  bellows::Adsr filt_;\n  bellows::LadderFilter ladder_;\n  Params p_;\n  float sr_ = 48000.0f;\n  int samples_per_step_ = 1;\n  int pos_ = 0;\n};\n\n}  // namespace firststeps\n";

export const fs_motion_h: string = "/* Step 4 of the 06_FirstSteps example: movement.\n *\n * Step 3 with an LFO, which is the last primitive you need before the\n * engines start doing the work for you. An envelope moves once per note. An\n * LFO moves whether or not anything is playing, and that difference is why\n * a patch with both sounds alive and a patch with neither sounds like a\n * sample.\n *\n * Two of them here, doing the two jobs LFOs actually do. A slow triangle\n * walks the filter cutoff across the whole note, which is the sweep you\n * hear on a pad. A fast sine moves the pitch by a few cents, which is\n * vibrato, and the depth is in cents rather than Hz on purpose: a fixed\n * number of Hz is a wide wobble low down and inaudible high up, because\n * pitch is logarithmic and Hz is not.\n *\n * The phase accumulator is a uint32 counter, not a float. A float\n * accumulator loses part of every increment to rounding as it approaches\n * 1.0, systematically rather than randomly, so the error grows with the\n * length of the note instead of averaging out. That was measured as the\n * whole of the chorus parity gap against the browser, 4e-2 with modulation\n * running against 6.3e-6 with it off, and the fix moved three parity rows.\n * The wrap is the natural unsigned overflow, so it costs neither a compare\n * nor a branch. See config.h. */\n#pragma once\n\n#include \"bellows/config.h\"\n#include \"bellows/core/fastmath.h\"\n#include \"bellows/dsp/envelopes.h\"\n#include \"bellows/dsp/filters.h\"\n#include \"bellows/dsp/lfo.h\"\n#include \"bellows/dsp/oscillators.h\"\n\nnamespace firststeps {\n\nclass Motion {\n public:\n  struct Params {\n    float freq = 165.0f;\n    float cutoff = 1500.0f;\n    float resonance = 0.6f;\n    /* How far the slow LFO opens and closes the filter, in octaves. */\n    float sweep_octaves = 2.2f;\n    float sweep_rate = 0.18f;\n    /* Vibrato, in cents so it is the same size at every pitch. */\n    float vibrato_cents = 12.0f;\n    float vibrato_rate = 5.2f;\n    float decay = 0.8f;\n    float level = 0.3f;\n  };\n\n  void Init(float sample_rate) {\n    Params p;\n    p.freq = 165.0f;\n    p.cutoff = 1500.0f;\n    p.resonance = 0.6f;\n    p.sweep_octaves = 2.2f;\n    p.sweep_rate = 0.18f;\n    p.vibrato_cents = 12.0f;\n    p.vibrato_rate = 5.2f;\n    p.decay = 0.8f;\n    p.level = 0.3f;\n    Init(sample_rate, p);\n  }\n\n  void Init(float sample_rate, const Params& p) {\n    sr_ = sample_rate;\n    osc_.Init(sample_rate);\n    osc_.SetShape(bellows::BlepShape::kSaw);\n    amp_.Init(sample_rate);\n    ladder_.Init(sample_rate);\n    sweep_.Init(sample_rate);\n    sweep_.SetShape(bellows::LfoShape::kTriangle);\n    vib_.Init(sample_rate);\n    vib_.SetShape(bellows::LfoShape::kSine);\n    SetParams(p);\n    SetTempo(120);\n  }\n\n  void SetParams(const Params& p) {\n    p_ = p;\n    amp_.Set(0.01f, p_.decay, 0.0f, 0.08f);\n    sweep_.SetFreq(p_.sweep_rate);\n    vib_.SetFreq(p_.vibrato_rate);\n  }\n\n  void SetTempo(unsigned bpm) {\n    /* Clamped before the divide: bpm 0 makes an infinity and casting that\n     * to int is undefined. */\n    if (bpm < 20u) bpm = 20u;\n    if (bpm > 400u) bpm = 400u;\n    float per_sec = static_cast<float>(bpm) / 60.0f;\n    samples_per_step_ = static_cast<int>(sr_ / per_sec + 0.5f);\n    if (samples_per_step_ < 2) samples_per_step_ = 2;\n  }\n\n  /* Both LFOs are stepped once per block, which is the rate the browser\n   * kernel steps a parameter ramp at and is far above anything audible in\n   * the movement itself. */\n  void operator()(float* l, float* r, int from, int to) {\n    const float sweep = 0.5f * (sweep_.Process() + 1.0f); /* 0 .. 1 */\n    const float cents = vib_.Process() * p_.vibrato_cents;\n    osc_.SetFreq(p_.freq * bellows::fm::Exp2(cents / 1200.0f));\n    ladder_.Set(p_.cutoff * bellows::fm::Exp2(sweep * p_.sweep_octaves), p_.resonance);\n\n    for (int i = from; i < to; ++i) {\n      if (pos_ == 0) amp_.Trigger();\n      const float s = ladder_.Process(osc_.Process()) * amp_.Process() * p_.level;\n      l[i] += s;\n      r[i] += s;\n      if (++pos_ >= samples_per_step_) pos_ = 0;\n    }\n  }\n\n private:\n  bellows::BlepOsc osc_;\n  bellows::Adsr amp_;\n  bellows::LadderFilter ladder_;\n  bellows::Lfo sweep_;\n  bellows::Lfo vib_;\n  Params p_;\n  float sr_ = 48000.0f;\n  int samples_per_step_ = 1;\n  int pos_ = 0;\n};\n\n}  // namespace firststeps\n";

export const workstation_h: string = "/* Shared logic for the 07_Workstation example.\n *\n * Every other example here teaches one idea. This one is the argument for\n * the library: five engines playing at once, a sequencer driving them from\n * the theory layer, an effect on a send, and one seed deciding the whole\n * thing, so two boards flashed with this file play the same four bars in\n * the same order for as long as they are both running.\n *\n * WHAT IS PLAYING\n *\n * Four bars of sixteenths in A natural minor, i VI iv v, one chord a bar.\n *\n *   kick    E(5,16)              Kick\n *   snare   E(4,16) rotated 4    Snare, on a send\n *   hat     E(11,16) rotated 1   Hat\n *   bass    E(3,16)              Va, the chord root, its fifth now and then\n *   melody  E(9,16) rotated 2    Pluck, four voices, notes from a Markov\n *                                chain, on a send\n *\n * The melody is the part worth reading. It is not a stored phrase: a\n * variable-order Markov chain is trained once on a sixteen note motif in\n * scale degrees, and every note after that is drawn from it, backing off\n * to a shorter context whenever the one it has was never seen.\n *\n * What that gives, measured over 20000 draws rather than assumed: the\n * chain plays five of the eight degrees, 0 2 4 5 7, because those are the\n * five the motif contains and a chain cannot invent a symbol it was never\n * trained on. The full sixteen note motif does turn up now and then, so\n * this is not a phrase generator that never quotes its source; it is the\n * motif as one path through the table among many, and which path you get\n * is decided by the seed.\n *\n * PITCH IS A LAYER, NOT A FORMULA\n *\n * Nothing here writes 440 * 2^((n - 69) / 12). A degree goes through\n * bellows::DegreeFreq with a Scale and a Tuning, which is what makes\n * 04_ScalesAndTuning's point reusable: change edo12_ to a 19-EDO tuning\n * and the whole piece transposes into it, motif, chords and bass line,\n * without touching a note of the arrangement.\n *\n * THE SEND BUS IS WRITTEN OUT BY HAND, BECAUSE THERE ISN'T ONE\n *\n * The TypeScript has b.bus() and inst.send(). This library deliberately\n * has no mixer: it is engines, effects and a kernel, and routing is the\n * application's business. So RenderSpan below IS the mixer, and it is\n * about fifteen lines. The one rule that shapes it is that a voice\n * advances its envelope when it renders, so a part that needs to go two\n * places has to be rendered ONCE into a scratch buffer and added twice.\n * Rendering it again would double its cost and desynchronise the copy.\n *\n * ONE ROOT, ONE STREAM PER PART\n *\n * bellows::Rng has no Fork(), and needs none: forking in the TypeScript is\n * literal string concatenation with \"::\", so writing the full path into\n * Init() lands on the same stream the browser is on. See core/prng.h. The\n * four labels below are that path written out, one per part, so the drums\n * cannot pull the melody off its sequence when a pattern changes.\n *\n * WHICH BOARDS, AND THE ANSWER WAS NOT THE ONE EXPECTED\n *\n * Teensy 4.0, 4.1 and MicroMod with room to spare, and 3.5 and 3.6 at 91.4\n * and 91.5 percent of their RAM, which is a fit with nothing left over.\n * Teensy 3.2 and LC do not fit at all. Those are build results from\n * examples/build-matrix.sh, not a reading of data sheets, and the 3.5 and\n * 3.6 columns were a surprise: this was written expecting 4.x only.\n *\n * The stereo delay is 500 ms at 48 kHz, 187 KB, which is most of the 225 KB\n * this costs and is more than a Teensy 3.2 has in total. It is deliberately\n * NOT scaled down per board the way 10_AudioShield's string floor is: a\n * composer patch that quietly becomes a different composer patch on a\n * smaller part is worse than one that says it does not fit. If you want it\n * on a 3.2, shorten the delay yourself and know that you did.\n *\n * None of that says any of those boards is fast enough. It fits, and 3.5\n * runs at 120 MHz against a 4.1's 600, so if anything here is going to run\n * out of time it is that one. Nobody has measured it.\n *\n * MEASURED COST, Cortex-M7, -Os, --gc-sections: see the report row for\n * p11_e7_workstation. */\n#pragma once\n\n#include \"bellows/config.h\"\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/drums.h\"\n#include \"bellows/engines/pluck.h\"\n#include \"bellows/engines/va.h\"\n#include \"bellows/fx/delay.h\"\n#include \"bellows/fx/dynamics.h\"\n#include \"bellows/fx/eq.h\"\n#include \"bellows/seq/euclid.h\"\n#include \"bellows/seq/markov.h\"\n#include \"bellows/theory/scales.h\"\n#include \"bellows/theory/tuning.h\"\n#include \"bellows/voicepool.h\"\n\nnamespace workstation {\n\ninline constexpr int kSteps = 16; /* sixteenths in a bar */\ninline constexpr int kBars = 4;\n\n/* i VI iv v in scale degrees. Degree 0 is the root of the scale, and\n * degrees past its length wrap into the next octave, so this stays\n * meaningful in any tuning. */\ninline constexpr int kProgression[kBars] = {0, 5, 3, 4};\n\n/* Scale degrees relative to the bar's chord, so the alphabet is eight\n * symbols: an octave of the scale plus the root above it. */\ninline constexpr int kAlphabet = 8;\n\n/* The motif the chain is trained on, once, at Init. Sixteen notes, two\n * phrases that answer each other. Nothing plays it: it is the statistics\n * that play. */\ninline constexpr uint8_t kMotif[] = {0, 2, 4, 2, 7, 4, 2, 0, 4, 5, 4, 2, 0, 2, 4, 7};\ninline constexpr int kMotifLen = static_cast<int>(sizeof(kMotif) / sizeof(kMotif[0]));\n\n/* Order 2 over eight symbols needs at most 1 + 8 + 64 contexts, and this\n * motif reaches 15 of them, counted. 48 leaves room to edit the motif\n * without silently dropping transitions; Truncated() reports it if you\n * overrun, and Init here checks it. */\nusing Chain = bellows::Markov<kAlphabet, 48, 2>;\n\n/* A 110 Hz floor is two octaves below the melody's lowest note, which\n * costs a fifth of what a 20 Hz floor would per voice. The floor is the\n * delay line and the delay line is the RAM. */\nusing String = bellows::Pluck<110>;\n\ninline constexpr int kVoices = 4;\n\n/* The scratch the hand-written send bus runs through. One block, matching\n * the kernel and the Teensy audio library. */\ninline constexpr int kMaxBlock = BELLOWS_BLOCK_SIZE;\n\nclass Piece {\n public:\n  void Init(float sample_rate, unsigned bpm) {\n    sr_ = sample_rate;\n    /* A second Init at a different rate used to re-init every unit except\n     * the delay, because SetTempo latches delay_ready_ and only calls\n     * SetParams after that. Measured: Init(48000) then Init(44100) left the\n     * echo 8.8 percent late, at 0.5102 s where a fresh Init gives 0.4688.\n     * Everything positional resets here too, so Init means Init. */\n    delay_ready_ = false;\n    step_ = 0;\n    countdown_ = 0;\n    bass_gate_ = 0;\n    frame_ = 0;\n    transpose_ = 0;\n    seed_ = 0;\n\n    /* One root, one stream per part. Nothing shares a stream, so changing\n     * a drum pattern cannot move the melody. */\n    rng_seq_.Init(\"workstation::seq\");\n    rng_melody_.Init(\"workstation::melody\");\n    rng_bass_.Init(\"workstation::bass\");\n    /* The JS snare forks 'snare/noise' off its channel stream, so this is\n     * the path that stream would have. */\n    rng_snare_.Init(\"workstation::kit::snare/noise\");\n\n    kick_.Init(sample_rate);\n    snare_.Init(sample_rate, &rng_snare_);\n    hat_.Init(sample_rate);\n\n    bellows::Va::Params bass;\n    bass.shape = 0.15f;      /* close to a saw, which the ladder likes */\n    bass.detune = 4.0f;\n    bass.sub = 0.6f;         /* the octave below is most of the weight */\n    bass.cutoff = 900.0f;\n    bass.resonance = 0.25f;\n    bass.env_amount = 0.4f;\n    bass.attack = 0.004f;\n    bass.decay = 0.18f;\n    bass.sustain = 0.45f;\n    bass.release = 0.12f;\n    bass_.Init(sample_rate, &rng_bass_, bass);\n\n    String::Params str;\n    str.damp = 0.32f;\n    str.pick_pos = 0.22f;\n    str.decay = 2.4f;\n    str.level = 0.8f;\n    for (int i = 0; i < kVoices; ++i) melody_.at(i).Init(sample_rate, &rng_melody_, str);\n\n    /* A minor, root index 57 which is A3. Bass plays an octave below it\n     * and the melody two above, by shifting the degree rather than the\n     * root, so one scale and one tuning serve all three parts. */\n    scale_.Init(57, bellows::kScaleMinor);\n    edo12_.InitEdo(12, 440.0f, 69);\n\n    for (int i = 0; i < kBars; ++i) prog_[i] = kProgression[i];\n    for (int i = 0; i < kMotifLen; ++i) motif_[i] = kMotif[i];\n    chain_.Init(2);\n    trained_ = chain_.Train(motif_, kMotifLen);\n    chain_.Seed(motif_, 2);\n\n    kick_pat_.Generate(5, kSteps);\n    snare_pat_.Generate(4, kSteps, 4);\n    hat_pat_.Generate(11, kSteps, 1);\n    bass_pat_.Generate(3, kSteps);\n    melody_pat_.Generate(9, kSteps, 2);\n\n    /* The last thing in the chain, exactly as b.masterFx(['limiter']) is\n     * in the browser. It is not gain staging: the mix below is set so the\n     * limiter takes a decibel or two off the loudest bars and nothing at\n     * all off the quiet ones. It is there because a converter clips and\n     * the piezo path in 15_Piezo has no headroom to give. */\n    bellows::Limiter<>::Params lim;\n    lim.ceiling_db = -1.0f;\n    lim.release = 0.08f;\n    limiter_.Init(sample_rate, lim);\n\n    bellows::Eq3::Params eq;\n    eq.low_freq = 110.0f;\n    eq.low_gain = 2.0f;    /* the kick and the sub, lifted a little */\n    eq.mid_freq = 800.0f;\n    eq.mid_gain = -2.5f;   /* room for the strings above the bass */\n    eq.mid_q = 0.8f;\n    eq.high_freq = 7000.0f;\n    eq.high_gain = 2.0f;\n    eq_.Init(sample_rate, eq);\n\n    SetTempo(bpm);\n  }\n\n  /* Tempo sets the step length AND the delay times, so the echo stays in\n   * time with the pattern instead of drifting against it. Left is a\n   * dotted eighth and right an eighth, which is the pairing that makes a\n   * stereo delay read as a rhythm rather than as a smear. */\n  void SetTempo(unsigned bpm) {\n    /* Clamp BEFORE the arithmetic. At bpm 0 the division gives an infinity\n     * and casting that to int is undefined: a Cortex-M7 saturates and the\n     * host traps, which is exactly the class of cast this library already\n     * hardened once in the delay line. */\n    if (bpm < 20u) bpm = 20u;\n    if (bpm > 400u) bpm = 400u;\n    bpm_ = bpm;\n    const float steps_per_sec = (static_cast<float>(bpm) / 60.0f) * 4.0f;\n    samples_per_step_ = static_cast<int>(sr_ / steps_per_sec + 0.5f);\n    if (samples_per_step_ < 1) samples_per_step_ = 1;\n\n    const float beat = 60.0f / static_cast<float>(bpm);\n    bellows::StereoDelay<500>::Params d;\n    d.time_l = beat * 0.75f;  /* dotted eighth */\n    d.time_r = beat * 0.5f;   /* eighth */\n    d.feedback = 0.42f;\n    d.cross_feedback = 0.18f;\n    d.damping = 4200.0f;      /* repeats get darker, so they sit behind */\n    d.mix = 1.0f;             /* a send carries the wet signal only */\n    if (delay_ready_) {\n      delay_.SetParams(d);\n    } else {\n      delay_.Init(sr_, d);\n      delay_ready_ = true;\n    }\n  }\n\n  /*\n   * Draw a fresh arrangement from a seed.\n   *\n   * Init() gives the piece written into this file, and calling nothing\n   * else keeps that: the size sketch and the parity work are unaffected.\n   * This re-draws the things that make one piece different from another,\n   * which is more than the notes. Tempo, mode, the four bar progression,\n   * all five euclidean rhythms and the motif the Markov chain is trained\n   * on all come from the seed, so two boots are two arrangements rather\n   * than the same arrangement with different dice.\n   *\n   * The seed is the whole contract. The library's promise is that a seed\n   * reproduces a piece, and that still holds here: keep the number and you\n   * can play this arrangement again, which is why the sketch prints it.\n   *\n   * Every draw is bounded to stay musical rather than merely different. A\n   * kick can be 3 to 6 pulses in 16 and not 1 to 15, the modes are all\n   * minor coloured so a progression written in degrees means the same\n   * thing in each, and bar 0 is always the tonic.\n   */\n  void Compose(uint32_t seed) {\n    seed_ = seed;\n    bellows::Rng r;\n    r.Init(seed);\n\n    /* Minor coloured modes only, so degrees keep their character. */\n    static const bellows::ScaleType kModes[] = {\n        bellows::kScaleMinor,          bellows::kScaleDorian,\n        bellows::kScaleHarmonicMinor,  bellows::kScaleMinorPentatonic,\n        bellows::kScalePhrygian,       bellows::kScaleKumoi,\n    };\n    scale_.Init(57, kModes[Draw(r, 6)]);\n    const int len = scale_.Length();\n\n    /* Bar 0 is the tonic. The rest come from degrees that resolve back to\n     * it: the fourth, the fifth, the sixth and the third. */\n    static const int kCandidates[] = {5, 3, 4, 2, 5, 4};\n    prog_[0] = 0;\n    for (int i = 1; i < kBars; ++i) prog_[i] = kCandidates[Draw(r, 6)] % (len > 1 ? len : 1);\n\n    kick_pat_.Generate(3 + Draw(r, 4), kSteps);\n    snare_pat_.Generate(2 + Draw(r, 3), kSteps, 4);\n    hat_pat_.Generate(7 + Draw(r, 7), kSteps, Draw(r, 4));\n    bass_pat_.Generate(3 + Draw(r, 3), kSteps);\n    melody_pat_.Generate(7 + Draw(r, 5), kSteps, Draw(r, 4));\n\n    /* A motif with stepwise bias, because a chain trained on leaps plays\n     * leaps. Steps of -2 to +2 in scale degrees, folded into the\n     * alphabet, which is what keeps it singable. */\n    int d = Draw(r, 3);\n    for (int i = 0; i < kMotifLen; ++i) {\n      motif_[i] = static_cast<uint8_t>(d);\n      d += Draw(r, 5) - 2;\n      if (d < 0) d += kAlphabet;\n      if (d >= kAlphabet) d -= kAlphabet;\n    }\n    chain_.Init(2);\n    trained_ = chain_.Train(motif_, kMotifLen);\n    chain_.Seed(motif_, 2);\n\n    SetTempo(84 + static_cast<unsigned>(Draw(r, 5)) * 7);\n  }\n\n  /* The seed this arrangement came from, or 0 for the written one. */\n  uint32_t Seed() const { return seed_; }\n\n  /* Shift every pitched part by whole octaves.\n   *\n   * The drums are deliberately unaffected: they tune from a fixed noteOn\n   * frequency rather than from a degree, so a kit stays a kit. This exists\n   * for output paths that cannot reproduce the bottom of the piece.\n   *\n   * A piezo disc motivated it and then argued against it. The reasoning\n   * was that a disc passes almost nothing at 100 Hz, so lifting the piece\n   * into its band should help. Measured through the 15_Piezo chain it does\n   * the opposite: 1.1 dB quieter at +1 octave and 2.2 dB at +2, because a\n   * plucked string carries less energy and decays faster the higher it is\n   * pitched, and that loses more than the disc's response gains. Gain into\n   * the limiter was worth 12 dB where this was worth less than nothing.\n   * Keep it for output paths where the arithmetic comes out differently,\n   * and measure before assuming it is one of them. */\n  void SetTranspose(int octaves) { transpose_ = octaves; }\n  int Transpose() const { return transpose_; }\n\n  /* True when the motif fitted the chain's table. False means transitions\n   * were dropped and the melody is a smaller chain than the one written. */\n  bool Trained() const { return trained_; }\n  int Bar() const { return (step_ / kSteps) % kBars; }\n  int Step16() const { return step_ % kSteps; }\n  unsigned Bpm() const { return bpm_; }\n  int Voices() const { return melody_.ActiveCount(); }\n\n  /* Advance the sequencer one step and fire whatever the patterns say. */\n  void Step() {\n    const int s = step_ % kSteps;\n    const int chord = prog_[Bar()];\n    /* An octave, in degrees of whatever scale is loaded. */\n    const int octave = scale_.Length();\n\n    if (kick_pat_.At(s)) kick_.NoteOn(50.0f, 0.95f);\n    if (snare_pat_.At(s)) snare_.NoteOn(190.0f, 0.7f + 0.2f * rng_seq_.Next());\n    if (hat_pat_.At(s)) hat_.NoteOn(330.0f, 0.3f + 0.25f * rng_seq_.Next());\n\n    /* Release before retriggering, so the bass is a line and not a drone.\n     * The countdown runs every step, including the ones it fires on. */\n    if (bass_gate_ > 0 && --bass_gate_ == 0) bass_.NoteOff();\n    if (bass_pat_.At(s)) {\n      /* The root, and its fifth about one note in six, which is enough\n       * movement to imply the chord without stating it. */\n      const int degree = chord - octave + (rng_seq_.Next() < 0.16f ? 4 : 0);\n      bass_.NoteOn(DegreeHz(degree), 0.85f);\n      bass_gate_ = 3;\n    }\n\n    if (melody_pat_.At(s)) {\n      uint8_t sym = 0;\n      if (chain_.Next(rng_seq_, &sym)) {\n        const int degree = chord + static_cast<int>(sym) + octave;\n        /* The note id is the degree, so a repeated note reuses its voice\n         * rather than stealing a ringing one. Plucks are never released:\n         * a string has no key to lift, and the pool frees a voice as soon\n         * as it has decayed. */\n        melody_.NoteOn(degree, DegreeHz(degree), 0.5f + 0.35f * rng_seq_.Next(), frame_);\n      }\n    }\n    ++step_;\n  }\n\n  /* Render one block, split wherever a step falls so a hit lands on the\n   * exact sample rather than on the block boundary, and again at kMaxBlock\n   * so the send scratch is never overrun. */\n  void operator()(float* l, float* r, int from, int to) {\n    int i = from;\n    while (i < to) {\n      if (countdown_ <= 0) {\n        Step();\n        countdown_ = samples_per_step_;\n      }\n      int span = to - i;\n      if (span > countdown_) span = countdown_;\n      if (span > kMaxBlock) span = kMaxBlock;\n      RenderSpan(l, r, i, span);\n      i += span;\n      countdown_ -= span;\n      frame_ += static_cast<uint32_t>(span);\n    }\n  }\n\n private:\n  /* rng.int(n) with the same truncation the JS uses. */\n  static int Draw(bellows::Rng& r, int n) {\n    int i = static_cast<int>(r.Next() * static_cast<float>(n));\n    if (i < 0) i = 0;\n    if (i >= n) i = n - 1;\n    return i;\n  }\n\n  float DegreeHz(int degree) const {\n    return bellows::DegreeFreq(edo12_, 57, scale_.Intervals(), scale_.Length(),\n                               degree + transpose_ * scale_.Length());\n  }\n\n  /*\n   * The mixer, in full.\n   *\n   * Every part goes through Mix, which gives it a fader and a send knob,\n   * because the drum engines have no level of their own: Kick::Params is\n   * tune, decay and drive, and how loud it sits against a bass line is a\n   * property of the arrangement rather than of the drum. Kick, hat and\n   * bass send nothing, since a long echo on the low end is mud and a hat\n   * through a dotted eighth just doubles the pattern.\n   *\n   * The bus then runs through the delay at mix 1, so what comes back is\n   * the echo alone, and the sum goes through the EQ and the limiter.\n   */\n  void RenderSpan(float* l, float* r, int from, int n) {\n    for (int i = 0; i < n; ++i) {\n      send_l_[i] = 0.0f;\n      send_r_[i] = 0.0f;\n    }\n\n    Mix(kick_, 0.55f, 0.0f, l, r, from, n);\n    Mix(snare_, 0.33f, 0.14f, l, r, from, n);\n    Mix(hat_, 0.2f, 0.0f, l, r, from, n);\n    Mix(bass_, 0.4f, 0.0f, l, r, from, n);\n    Mix(melody_, 0.36f, 0.26f, l, r, from, n);\n\n    delay_.Process(send_l_, send_r_, 0, n);\n    for (int i = 0; i < n; ++i) {\n      l[from + i] += send_l_[i];\n      r[from + i] += send_r_[i];\n    }\n\n    eq_.Process(l, r, from, from + n);\n    limiter_.Process(l, r, from, from + n);\n  }\n\n  /* Render one part into the scratch, add it to the mix at `dry`, and add\n   * it to the send bus at `send`.\n   *\n   * Rendering the part a second time into the bus is what this exists to\n   * avoid: a voice advances its envelope when it renders, so the second\n   * copy would be a different signal and would cost a second voice. */\n  template <class Part>\n  void Mix(Part& part, float dry, float send, float* l, float* r, int from, int n) {\n    for (int i = 0; i < n; ++i) {\n      dry_l_[i] = 0.0f;\n      dry_r_[i] = 0.0f;\n    }\n    part.Process(dry_l_, dry_r_, 0, n);\n    for (int i = 0; i < n; ++i) {\n      l[from + i] += dry * dry_l_[i];\n      r[from + i] += dry * dry_r_[i];\n      send_l_[i] += send * dry_l_[i];\n      send_r_[i] += send * dry_r_[i];\n    }\n  }\n\n  bellows::Rng rng_seq_;\n  bellows::Rng rng_melody_;\n  bellows::Rng rng_bass_;\n  bellows::Rng rng_snare_;\n\n  bellows::Kick kick_;\n  bellows::Snare snare_;\n  bellows::Hat hat_;\n  bellows::Va bass_;\n  bellows::VoicePool<String, kVoices> melody_;\n\n  bellows::StereoDelay<500> delay_;\n  bellows::Eq3 eq_;\n  bellows::Limiter<> limiter_;\n\n  bellows::Scale scale_;\n  bellows::Tuning12 edo12_;\n  Chain chain_;\n\n  bellows::Euclid<kSteps> kick_pat_;\n  bellows::Euclid<kSteps> snare_pat_;\n  bellows::Euclid<kSteps> hat_pat_;\n  bellows::Euclid<kSteps> bass_pat_;\n  bellows::Euclid<kSteps> melody_pat_;\n\n  float send_l_[kMaxBlock] = {};\n  float send_r_[kMaxBlock] = {};\n  float dry_l_[kMaxBlock] = {};\n  float dry_r_[kMaxBlock] = {};\n\n  float sr_ = 48000.0f;\n  unsigned bpm_ = 96;\n  int samples_per_step_ = 1;\n  int countdown_ = 0;\n  int step_ = 0;\n  int bass_gate_ = 0;\n  int transpose_ = 0;\n  uint32_t frame_ = 0;\n  uint32_t seed_ = 0;\n  int prog_[kBars] = {0, 0, 0, 0};\n  uint8_t motif_[kMotifLen] = {};\n  bool trained_ = false;\n  bool delay_ready_ = false;\n};\n\n}  // namespace workstation\n";

export const workstation_ino: string = "/*\n * 07_Workstation: five engines, a sequencer and a send, from one seed.\n *\n * The other examples each teach one thing. This one is what they add up\n * to: a kit on euclidean rhythms, a bass line, a plucked melody whose\n * notes come out of a Markov chain rather than an array, a tempo-synced\n * stereo delay on a send, an EQ and a limiter on the master. Nothing is\n * stored except a sixteen note motif, and nothing is random except in the\n * sense that it comes from a named stream, so two boards running this\n * play the same piece.\n *\n * It loops four bars of A minor at 96 bpm and never repeats a bar exactly,\n * because the melody is drawn rather than read.\n *\n * BOARDS\n *   Teensy 4.0, 4.1 and MicroMod with room to spare; 3.5 and 3.6 at 91.4\n *   and 91.5 percent of RAM, which fits and leaves nothing. Not 3.2 and\n *   not LC: the 500 ms stereo delay line is 187 KB on its own, which is\n *   more than a 3.2 has in total. Those are build results from\n *   examples/build-matrix.sh. Whether a 120 MHz 3.5 keeps up is a\n *   different question and is unmeasured.\n *\n *   There is deliberately no #error for the two that do not fit. 12_DacOut\n *   uses one because a Teensy 4.x has no DAC at all and never will, which\n *   is categorical. Not enough RAM is a quantity, and \"region RAM\n *   overflowed by N bytes\" tells you how much you would have to give up.\n *   That is why the matrix shows RAM here and n/a there.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack. For any other way of getting sound out, see\n *   examples 11 to 15 and examples/OUTPUTS.md: this sketch's node is\n *   wired the same way theirs are.\n *\n * WHAT IS VERIFIED\n *   The header compiles standalone, links as firmware for the boards\n *   above, and the piece was rendered offline and measured: two Pieces\n *   with the same seed produce 0 differing samples over 30 seconds, every\n *   melody and bass pitch lands in A minor, the kick onsets fall on\n *   E(5,16), and the left delay tap shows an autocorrelation of 0.57 at\n *   the dotted eighth against 0.03 to 0.08 at neighbouring lags. Nothing\n *   here has been flashed to a board. See examples/README.md.\n *\n * PORTING\n *   To a Daisy Seed: swap bellows/platform/teensy.h for\n *   bellows/platform/daisy.h and start the audio through DaisyAudio<T>\n *   instead of an AudioStream node. The header below does not change.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"workstation.h\"\n\nstatic workstation::Piece piece;\n\nstatic bellows::BellowsAudioStream<workstation::Piece> node(piece);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  Serial.begin(115200);\n  /* More blocks than the smaller examples, because five parts and a send\n   * bus is more work per callback than one voice is. */\n  piece.Init(bellows::TeensySampleRate(), 96);\n  /* AudioMemory LAST, and this ordering is load bearing.\n   *\n   * BellowsAudioStream::update() returns early only while allocate() is\n   * null, which is to say only until AudioMemory() runs. After that the\n   * audio interrupt renders whatever it is pointed at, so anything\n   * initialised below this line can be rendered before it is ready. A\n   * delay line that has not been given its buffer reads through a null\n   * pointer, which on an IMXRT1062 is executable memory rather than a\n   * trap page. */\n  AudioMemory(24);\n  codec.enable();\n  codec.volume(0.6f);\n\n  /* Train() is the one call here that can fail: the motif is bigger than\n   * the chain's table only if you edit it, and a chain that dropped\n   * transitions plays a smaller chain with no other symptom. */\n  if (!piece.Trained()) Serial.println(\"workstation: markov table full, melody is truncated\");\n}\n\nvoid loop() {\n  /* The sequencer runs inside the audio callback, so the loop has nothing\n   * to do but report. AudioProcessorUsageMax is the number Milestone 1\n   * exists to collect: this is the heaviest sketch in the set. */\n  delay(2000);\n  Serial.print(\"bar \");\n  Serial.print(piece.Bar() + 1);\n  Serial.print(\"/4  voices \");\n  Serial.print(piece.Voices());\n  Serial.print(\"  cpu \");\n  Serial.print(AudioProcessorUsage(), 1);\n  Serial.print(\"%  peak \");\n  Serial.print(AudioProcessorUsageMax(), 1);\n  Serial.println(\"%\");\n}\n";

export const instruments_ino: string = "/*\n * 20_Instruments: ten instruments, one program.\n *\n * A patch library rather than a lesson. Each header in this folder is one\n * instrument, self contained, with its parameters written out and a\n * comment saying what makes it that instrument rather than another one:\n *\n *   epiano.h       FM electric piano, the DX tine\n *   acid.h         resonant mono bass, the filter IS the instrument\n *   junopad.h      chorused polysynth pad\n *   westcoast.h    wavefolder and low pass gate, no filter at all\n *   guitar.h       Karplus-Strong plucked string\n *   bells.h        modal, bell partials with the minor third at 2.4\n *   marimba.h      modal, wood. The same engine, four numbers different\n *   glass.h        modal, sparse partials that keep their brightness\n *   clarinet.h     waveguide with a reed, driven rather than struck\n *   choir.h        formant vowels, morphed in the log domain\n *   eightoheight.h the long-decay kit\n *\n * They share `player.h`, which holds the scale, the tuning, the chord\n * progression and the rhythms, so switching patch compares INSTRUMENTS and\n * not the parts they happen to be playing. That is the same argument\n * 10_AudioShield makes for the output examples sharing one chord.\n *\n * The sketch plays each for four bars and moves on. All eleven are linked\n * into this one image, which is the honest way to size it: the matrix row\n * in examples/README.md is the whole book, not the cheapest patch in it.\n *\n * Dispatch is bellows::Bank, a runtime index resolved through\n * compile-time-generated compares. No vtable, no registry, no string\n * lookup. docs/HANDOFF.md records what a string-keyed registry of five\n * engines costs instead: 30488 bytes of flash against 3760 direct, because\n * naming every engine forces the linker to keep every engine.\n *\n * BOARDS\n *   See the matrix in examples/README.md. It is a build log rather than a\n *   reading of data sheets, and nothing here says any board is fast\n *   enough: no bellows program has been run on hardware.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack.\n *\n * WHAT IS VERIFIED\n *   Every header compiles standalone, all of them link as one image, and\n *   each patch was rendered offline and measured for level, for non-finite\n *   samples and for pitch. Nothing here has been flashed to a board.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/bank.h\"\n#include \"bellows/fx/dynamics.h\"\n#include \"bellows/platform/teensy.h\"\n\n#include \"acid.h\"\n#include \"bells.h\"\n#include \"choir.h\"\n#include \"clarinet.h\"\n#include \"eightoheight.h\"\n#include \"epiano.h\"\n#include \"glass.h\"\n#include \"guitar.h\"\n#include \"junopad.h\"\n#include \"marimba.h\"\n#include \"player.h\"\n#include \"westcoast.h\"\n\n/* Declaration order is dispatch order and is the order of the tour. */\nenum Instrument {\n  kEpiano = 0, kAcid, kJunoPad, kWestCoast, kGuitar,\n  kBells, kMarimba, kGlass, kClarinet, kChoir, kEightOhEight,\n  kInstrumentCount\n};\n\nstatic const char* kName[kInstrumentCount] = {\n    \"epiano\", \"acid\", \"junopad\", \"westcoast\", \"guitar\",\n    \"bells\", \"marimba\", \"glass\", \"clarinet\", \"choir\", \"808\",\n};\n\n/* Per patch output trim, measured. See the note at the top of any patch\n * header: the engines have no common loudness reference, so without this\n * changing instrument means reaching for the volume. */\nstatic const float kTrims[kInstrumentCount] = {\n    epiano::kTrim, acid::kTrim, junopad::kTrim, westcoast::kTrim, guitar::kTrim,\n    bells::kTrim, marimba::kTrim, glass::kTrim, clarinet::kTrim, choir::kTrim,\n    eightoheight::kTrim,\n};\n\nstatic const player::Kind kKinds[kInstrumentCount] = {\n    epiano::kKind, acid::kKind, junopad::kKind, westcoast::kKind, guitar::kKind,\n    bells::kKind, marimba::kKind, glass::kKind, clarinet::kKind, choir::kKind,\n    eightoheight::kKind,\n};\n\nstatic bellows::Bank<epiano::Patch, acid::Patch, junopad::Patch, westcoast::Patch,\n                     guitar::Patch, bells::Patch, marimba::Patch, glass::Patch,\n                     clarinet::Patch, choir::Patch, eightoheight::Patch>\n    book;\n\n/*\n * The shell: one sequencer, one patch sounding at a time, block split at\n * the step boundary so a note lands on the sample rather than on the block\n * edge. Everything musical comes from `player`.\n */\nclass Book {\n public:\n  void Init(float sample_rate) {\n    sr_ = sample_rate;\n    rng_.Init(\"instruments\");\n    play_.Init();\n    book.ForEach([this, sample_rate](auto& patch) { patch.Init(sample_rate, &rng_); });\n\n    /* The trims put every patch at about the same RMS. The limiter is for\n     * what a trim cannot fix: a plucked chord and a kick are transients\n     * with a crest factor above 30 dB, so the peak that matters is one\n     * sample long and pulling the whole patch down to fit it would leave\n     * it inaudible. */\n    bellows::Limiter<>::Params lim;\n    lim.ceiling_db = -1.0f;\n    lim.release = 0.06f;\n    limiter_.Init(sample_rate, lim);\n\n    SetTempo(96);\n  }\n\n  void SetTempo(unsigned bpm) {\n    const float steps_per_sec = (static_cast<float>(bpm) / 60.0f) * 4.0f;\n    samples_per_step_ = static_cast<int>(sr_ / steps_per_sec + 0.5f);\n    if (samples_per_step_ < 1) samples_per_step_ = 1;\n  }\n\n  void Select(int i) {\n    if (i == which_) return;\n    /* Release whatever the outgoing patch is holding, or a pad sustains\n     * under the next instrument for the rest of the tour. */\n    AllOff();\n    which_ = i;\n    step_ = 0;\n  }\n\n  int Selected() const { return which_; }\n  int Bar() const { return (step_ / player::kSteps) % player::kBars; }\n\n  void Step() {\n    const int s = step_ % player::kSteps;\n    const int bar = Bar();\n\n    switch (kKinds[which_]) {\n      case player::Kind::kChord:\n        /* One voicing a bar, held until the next one. */\n        if (s == 0) {\n          AllOff();\n          int deg[3];\n          const int n = play_.ChordDegrees(bar, deg);\n          for (int i = 0; i < n; ++i) {\n            book.With(which_, [&](auto& p) { p.NoteOn(deg[i], play_.Hz(deg[i]), 0.62f); });\n            held_[i] = deg[i];\n          }\n          held_count_ = n;\n        }\n        break;\n\n      case player::Kind::kMelody: {\n        const int d = play_.MelodyDegree(bar, s);\n        if (d != player::kRest) {\n          book.With(which_, [&](auto& p) { p.NoteOn(d, play_.Hz(d), 0.7f); });\n        }\n        break;\n      }\n\n      case player::Kind::kBass: {\n        const int d = play_.BassDegree(bar, s);\n        if (d != player::kRest) {\n          /* Accent every fourth step, which is what moves the filter. */\n          const float vel = (s % 4 == 0) ? 0.95f : 0.55f;\n          book.With(which_, [&](auto& p) { p.NoteOn(d, play_.Hz(d), vel); });\n        }\n        break;\n      }\n\n      case player::Kind::kPercussion:\n        if (play_.Kick(s)) book.With(which_, [](auto& p) { p.NoteOn(0, 0.0f, 0.95f); });\n        if (play_.Snare(s)) book.With(which_, [](auto& p) { p.NoteOn(1, 0.0f, 0.75f); });\n        if (play_.Hat(s)) book.With(which_, [](auto& p) { p.NoteOn(2, 0.0f, 0.45f); });\n        break;\n    }\n    ++step_;\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    int i = from;\n    while (i < to) {\n      if (countdown_ <= 0) {\n        Step();\n        countdown_ = samples_per_step_;\n      }\n      int span = to - i;\n      if (span > countdown_) span = countdown_;\n      if (span > kMaxBlock) span = kMaxBlock;\n      /* Patches ADD, so a patch is rendered into the scratch and trimmed\n       * on the way out rather than being asked to know how loud it should\n       * be relative to ten others it has never heard of. */\n      for (int k = 0; k < span; ++k) {\n        scratch_l_[k] = 0.0f;\n        scratch_r_[k] = 0.0f;\n      }\n      book.With(which_, [this, span](auto& p) { p(scratch_l_, scratch_r_, 0, span); });\n      const float g = kTrims[which_];\n      for (int k = 0; k < span; ++k) {\n        l[i + k] += g * scratch_l_[k];\n        r[i + k] += g * scratch_r_[k];\n      }\n      limiter_.Process(l, r, i, i + span);\n      i += span;\n      countdown_ -= span;\n    }\n  }\n\n private:\n  void AllOff() {\n    for (int i = 0; i < held_count_; ++i) {\n      const int id = held_[i];\n      book.With(which_, [id](auto& p) { p.NoteOff(id); });\n    }\n    held_count_ = 0;\n  }\n\n  static constexpr int kMaxBlock = BELLOWS_BLOCK_SIZE;\n\n  bellows::Rng rng_;\n  player::Player play_;\n  bellows::Limiter<> limiter_;\n  float scratch_l_[kMaxBlock] = {};\n  float scratch_r_[kMaxBlock] = {};\n  float sr_ = 48000.0f;\n  int samples_per_step_ = 1;\n  int countdown_ = 0;\n  int step_ = 0;\n  int which_ = 0;\n  int held_[3] = {0, 0, 0};\n  int held_count_ = 0;\n};\n\nstatic Book bk;\n\nstatic bellows::BellowsAudioStream<Book> node(bk);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  Serial.begin(115200);\n  codec.enable();\n  codec.volume(0.6f);\n  bk.Init(bellows::TeensySampleRate());\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(20);\n}\n\nvoid loop() {\n  for (int i = 0; i < kInstrumentCount; ++i) {\n    bk.Select(i);\n    Serial.print(\"patch \");\n    Serial.print(i + 1);\n    Serial.print(\"/\");\n    Serial.print(static_cast<int>(kInstrumentCount));\n    Serial.print(\"  \");\n    Serial.print(kName[i]);\n    Serial.print(\"   cpu \");\n    Serial.print(AudioProcessorUsageMax(), 1);\n    Serial.println(\"%\");\n    AudioProcessorUsageMaxReset();\n    /* Four bars of sixteenths at 96 bpm is exactly 10 seconds. */\n    delay(10000);\n  }\n}\n";

export const player_h: string = "/* The note source shared by every patch in the 20_Instruments example.\n *\n * The patches are sounds. This is the music, kept in one file so that\n * comparing two patches compares the instruments and not the parts they\n * happen to be playing, the same argument 10_AudioShield makes for the\n * output examples sharing one chord.\n *\n * Everything is scale degrees, never note numbers, and a degree becomes a\n * frequency through bellows::DegreeFreq with a Scale and a Tuning. Swap\n * edo12_ for a 19-EDO tuning and the whole example moves into it, every\n * patch, without a line of the arrangement changing. That is the point\n * 04_ScalesAndTuning makes at length and this one gets for free.\n *\n * A patch declares what KIND of part it wants, and gets a different one:\n *\n *   kChord       a voicing on the bar, held. Pads, keys, choirs.\n *   kMelody      a line on a euclidean rhythm. Leads, bells, winds.\n *   kBass        roots and fifths, low and short.\n *   kPercussion  a gate per pad, no pitch from here.\n *\n * That is four parts rather than one because an electric piano and a\n * clarinet do not want the same notes, and giving them the same notes is\n * how a patch library ends up sounding like one patch.\n */\n#pragma once\n\n#include <stdint.h>\n\n#include \"bellows/seq/euclid.h\"\n#include \"bellows/theory/scales.h\"\n#include \"bellows/theory/tuning.h\"\n\nnamespace player {\n\nenum class Kind : uint8_t { kChord, kMelody, kBass, kPercussion };\n\ninline constexpr int kSteps = 16;\ninline constexpr int kBars = 4;\n\n/* i VI iv v in A natural minor, one chord a bar. */\ninline constexpr int kProgression[kBars] = {0, 5, 3, 4};\n\n/* A sixteen step line in degrees relative to the bar's chord. Rests are\n * kRest, which is outside any degree the scale can produce. */\ninline constexpr int kRest = -99;\ninline constexpr int kLine[kSteps] = {0,  kRest, 4, kRest, 2, kRest, kRest, 7,\n                                      4, kRest, 2, 0,     kRest, 4, kRest, 2};\n\n/* Root index of the scale in the tuning. 57 is A3 in 12-EDO. */\ninline constexpr int kRootIndex = 57;\n\nclass Player {\n public:\n  void Init() {\n    scale_.Init(kRootIndex, bellows::kScaleMinor);\n    edo12_.InitEdo(12, 440.0f, 69);\n    melody_gate_.Generate(9, kSteps, 2);\n    bass_gate_.Generate(3, kSteps);\n    kick_gate_.Generate(5, kSteps);\n    snare_gate_.Generate(4, kSteps, 4);\n    hat_gate_.Generate(11, kSteps, 1);\n  }\n\n  int Octave() const { return scale_.Length(); }\n  int Chord(int bar) const { return kProgression[bar % kBars]; }\n\n  /* Frequency of a degree, through the tuning layer. */\n  float Hz(int degree) const {\n    return bellows::DegreeFreq(edo12_, kRootIndex, scale_.Intervals(), scale_.Length(), degree);\n  }\n\n  /* Three voices of the bar's chord, an octave up. Written into `out` as\n   * degrees; returns how many. */\n  int ChordDegrees(int bar, int* out) const {\n    const int c = Chord(bar);\n    const int oct = scale_.Length();\n    out[0] = c + oct;\n    out[1] = c + 2 + oct;\n    out[2] = c + 4 + oct;\n    return 3;\n  }\n\n  /* Melody degree for a step, or kRest. Two octaves above the root. */\n  int MelodyDegree(int bar, int step) const {\n    if (!melody_gate_.At(step)) return kRest;\n    const int d = kLine[step % kSteps];\n    if (d == kRest) return kRest;\n    return Chord(bar) + d + 2 * scale_.Length();\n  }\n\n  /* Bass degree for a step, or kRest. An octave below the root. */\n  int BassDegree(int bar, int step) const {\n    if (!bass_gate_.At(step)) return kRest;\n    return Chord(bar) - scale_.Length();\n  }\n\n  bool Kick(int step) const { return kick_gate_.At(step); }\n  bool Snare(int step) const { return snare_gate_.At(step); }\n  bool Hat(int step) const { return hat_gate_.At(step); }\n\n private:\n  bellows::Scale scale_;\n  bellows::Tuning12 edo12_;\n  bellows::Euclid<kSteps> melody_gate_;\n  bellows::Euclid<kSteps> bass_gate_;\n  bellows::Euclid<kSteps> kick_gate_;\n  bellows::Euclid<kSteps> snare_gate_;\n  bellows::Euclid<kSteps> hat_gate_;\n};\n\n}  // namespace player\n";

export const epiano_h: string = "/* 20_Instruments patch: FM electric piano.\n *\n * The sound the DX7 sold a million of, and the reason it did is one\n * arrangement of two operators: a carrier at the fundamental and a\n * modulator a long way above it, with the modulator's envelope decaying\n * much faster than the carrier's. That gives a bright metallic strike that\n * dies away in a fraction of a second over a soft sustained body, which is\n * exactly what a tine and a pickup do and nothing like what a filter\n * sweep does.\n *\n * The numbers that matter here are the ratios. Ratio 1 is the\n * fundamental; ratio 14 is the tine, high and deliberately not a whole\n * multiple of anything you would call harmonic, which is why it reads as a\n * strike rather than as a note. Move it to 2 and this becomes an organ.\n *\n * Brightness scales the modulator depth, so it is the velocity knob a real\n * one has: hit it harder and the tine speaks louder before it dies. That\n * is wired to velocity through vel, not to a parameter, because it is a\n * property of playing rather than of the patch.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/fm.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace epiano {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 0.47f;\n\ninline constexpr player::Kind kKind = player::Kind::kChord;\ninline constexpr int kVoices = 4;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng*) {\n    bellows::Fm::Params p;\n    p.ops = 4.0f;\n    p.algorithm = 5.0f;   /* two carrier and modulator pairs */\n    p.feedback = 0.12f;   /* a little grit on the strike */\n    p.brightness = 0.62f;\n    p.attack = 0.002f;\n    p.decay = 1.6f;\n    p.sustain = 0.28f;\n    p.release = 0.5f;\n    /* The tine: fast attack, fast decay, nothing held. */\n    p.m_attack = 0.001f;\n    p.m_decay = 0.16f;\n    p.m_sustain = 0.0f;\n    p.m_release = 0.12f;\n    p.ratio[0] = 1.0f;\n    p.ratio[1] = 14.0f;   /* the tine, high and inharmonic on purpose */\n    p.ratio[2] = 1.0f;\n    p.ratio[3] = 1.0f;\n    p.level[0] = 1.0f;\n    p.level[1] = 0.42f;\n    p.level[2] = 0.5f;\n    p.level[3] = 0.22f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, p);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::Fm, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace epiano\n";

export const acid_h: string = "/* 20_Instruments patch: acid bass.\n *\n * One oscillator, one filter, and the filter is the instrument. A 303 has\n * no second oscillator, no chorus and no reverb, and it has been the sound\n * of a genre for forty years because of what its envelope does to a\n * resonant lowpass: a fast, deep sweep on every note, deep enough that the\n * filter's own resonant peak is the loudest thing in the sound for the\n * first tenth of a second.\n *\n * So the numbers here are lopsided on purpose. Resonance sits at 0.88,\n * which is close enough to self-oscillation that the peak sings. The\n * filter envelope decays in 180 ms while the amplitude envelope takes\n * 400, so the brightness is gone long before the note is. env_amount is\n * most of the range rather than a seasoning.\n *\n * Accent is velocity, and it moves the filter rather than the volume,\n * which is `vel_filter`. That is the one control that makes a line of\n * sixteenths sound played rather than typed, and it is why the player\n * gives this patch a euclidean rhythm instead of a straight run.\n */\n#pragma once\n\n#include \"bellows/engines/va.h\"\n\n#include \"player.h\"\n\nnamespace acid {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 1.54f;\n\ninline constexpr player::Kind kKind = player::Kind::kBass;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Va::Params p;\n    p.shape = 0.0f;        /* saw. A square here is the other classic */\n    p.detune = 0.0f;       /* one oscillator, as the original has */\n    p.sub = 0.0f;\n    p.cutoff = 320.0f;     /* where the sweep lands, not where it starts */\n    p.resonance = 0.88f;   /* close enough to sing */\n    p.env_amount = 0.85f;  /* most of the range: this is the sound */\n    p.attack = 0.002f;\n    p.decay = 0.4f;\n    p.sustain = 0.0f;\n    p.release = 0.06f;\n    p.f_attack = 0.001f;\n    p.f_decay = 0.18f;     /* brightness gone well before the note is */\n    p.f_sustain = 0.0f;\n    p.f_release = 0.05f;\n    p.vel_level = 0.2f;\n    p.vel_filter = 0.8f;   /* accent moves the filter, not the volume */\n    voice_.Init(sample_rate, rng, p);\n  }\n\n  /* Monophonic, like the machine. A new note simply retriggers. */\n  void NoteOn(int, float hz, float vel) { voice_.NoteOn(hz, vel); }\n  void NoteOff(int) { voice_.NoteOff(); }\n\n  void operator()(float* l, float* r, int from, int to) { voice_.Process(l, r, from, to); }\n\n private:\n  bellows::Va voice_;\n};\n\n}  // namespace acid\n";

export const junopad_h: string = "/* 20_Instruments patch: chorused polysynth pad.\n *\n * The Juno trick, which is not a synthesis trick at all. The voice is\n * ordinary: one saw, a gentle lowpass, a slow attack. What made those\n * machines sound twice their size is a bucket-brigade chorus across the\n * whole output, so a single oscillator arrives at your ears twice with a\n * slowly varying delay between the copies, and the interference does the\n * widening.\n *\n * That is why the chorus is on the patch rather than on a send. It is not\n * an effect applied to this sound, it IS the sound, and turning mix to 0\n * leaves a thin four-voice pad that nobody would have bought.\n *\n * The sub oscillator is doing the other half of the work. A pad with no\n * bottom sits on top of a mix instead of in it, and one square an octave\n * down at 0.45 is cheaper than a second full oscillator and mostly\n * indistinguishable underneath a chorus.\n *\n * Slow attack means voices overlap, so the pool is four and steals from\n * the oldest released voice first. Drop it to two and the chords tear.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/va.h\"\n#include \"bellows/fx/modfx.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace junopad {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 0.49f;\n\ninline constexpr player::Kind kKind = player::Kind::kChord;\ninline constexpr int kVoices = 4;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Va::Params p;\n    p.shape = 0.08f;      /* saw with a hint of the square in it */\n    p.detune = 11.0f;\n    p.sub = 0.45f;        /* the octave below, which is the body */\n    p.cutoff = 2400.0f;\n    p.resonance = 0.12f;  /* almost none: the chorus is the character */\n    p.env_amount = 0.25f;\n    p.attack = 0.45f;     /* slow enough that chords bloom */\n    p.decay = 0.6f;\n    p.sustain = 0.8f;\n    p.release = 1.4f;\n    p.f_attack = 0.6f;\n    p.f_decay = 1.0f;\n    p.f_sustain = 0.6f;\n    p.f_release = 1.2f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, rng, p);\n\n    bellows::Chorus<>::Params c;\n    c.rate = 0.62f;\n    c.depth = 0.55f;\n    c.mix = 0.5f;         /* the whole point. At 0 this is a thin pad */\n    c.feedback = 0.1f;\n    chorus_.Init(sample_rate, c);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    /* In place across the whole patch, which is where a Juno's chorus is:\n     * after the voice mix, not per voice. */\n    chorus_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::Va, kVoices> pool_;\n  bellows::Chorus<> chorus_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace junopad\n";

export const westcoast_h: string = "/* 20_Instruments patch: west coast complex oscillator.\n *\n * The other tradition. East coast synthesis starts with a harmonically\n * rich waveform and takes things away with a filter; west coast starts\n * with a sine and MAKES harmonics, by folding the waveform back on itself\n * every time it exceeds a threshold. There is no filter in this patch at\n * all.\n *\n * Folding is loud in a way subtraction is not. Each fold adds a corner to\n * the waveform, and a corner is a whole series of harmonics, so driving\n * the folder harder does not make the sound louder so much as denser. The\n * fold envelope is therefore the main gesture: fold_env moves the drive\n * across the note, so a struck note starts dense and thins out, which is\n * how a real physical resonator behaves and is what a filter sweep is\n * imitating from the other direction.\n *\n * The low pass gate is the other half of the idea, and it is not a VCA. A\n * vactrol responds slowly and unevenly, and it closes brightness and\n * volume TOGETHER, so quiet also means dull. That coupling is why this\n * sounds like something being struck rather than something being turned\n * down, and lpg_decay is the knob that decides whether it is a bongo or a\n * bass.\n *\n * The fold chain runs at 4x internally with an antialiasing filter, added\n * after an audit found it folding at 1x and aliasing loudly. It is the\n * most expensive patch here for that reason.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/westcoast.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace westcoast {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 1.81f;\n\ninline constexpr player::Kind kKind = player::Kind::kMelody;\ninline constexpr int kVoices = 2;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng*) {\n    bellows::WestCoast::Params p;\n    p.fold_amount = 0.55f;   /* how hard the sine is driven into the folds */\n    p.fold_stages = 3.0f;    /* how many times it can turn back */\n    p.fold_env = 0.65f;      /* dense on the strike, thinner as it decays */\n    p.lpg_color = 0.6f;      /* vactrol: quiet and dull arrive together */\n    p.lpg_decay = 0.42f;\n    p.level = 0.7f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, p);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::WestCoast, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace westcoast\n";

export const guitar_h: string = "/* 20_Instruments patch: plucked string.\n *\n * Karplus-Strong, which is the cheapest convincing physical model there\n * is: fill a delay line one period long with noise, then read it out and\n * feed it back through a gentle lowpass. The noise is the pluck, the delay\n * length is the pitch, and the lowpass is why the sound gets darker as it\n * decays, exactly as a real string does because its high partials lose\n * energy fastest.\n *\n * Two things here are not the textbook version and both matter.\n *\n * The delay is read with cubic interpolation at a fractional length. An\n * integer-rounded loop is in tune at the bottom of the range and 28 cents\n * flat by E7, because the rounding error is a fixed number of samples and\n * a sample is a bigger fraction of a short period. There is a test that\n * holds every pitched engine to 2 cents specifically to keep that fixed.\n *\n * pick_pos is a comb filter on the excitation, standing in for where along\n * the string you struck it. Near the bridge (small values) is thin and\n * bright; a quarter of the way along is the guitar sound. It is one delay\n * and a subtraction and it does more for realism than anything else in\n * the patch.\n *\n * The 110 Hz floor is a memory decision, not a musical one. The delay line\n * has to hold one period of the LOWEST note, so a 20 Hz floor is 9.6 KB\n * per voice at 48 kHz and a 110 Hz floor is a fifth of that. Four voices\n * of the first is 38 KB; a Teensy 3.2 has 64 KB with the audio library\n * already in it. Pluck::MinFreq() reports what you actually got.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/pluck.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace guitar {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 3.40f;\n\ninline constexpr player::Kind kKind = player::Kind::kChord;\ninline constexpr int kVoices = 4;\n\nusing String = bellows::Pluck<110>;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    String::Params p;\n    p.damp = 0.28f;       /* how fast the top comes off. Higher is duller */\n    p.pick_pos = 0.24f;   /* about where a plectrum lands */\n    p.excite_type = 0.0f; /* noise burst rather than an impulse */\n    p.decay = 3.2f;\n    p.level = 0.75f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, rng, p);\n  }\n\n  /* A string has no key to lift, so NoteOff is deliberately a palm mute\n   * rather than a release, and the player does not use it. The pool frees\n   * a voice as soon as it has decayed. */\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<String, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace guitar\n";

export const bells_h: string = "/* 20_Instruments patch: tubular bells.\n *\n * Modal synthesis, which is the most direct kind of physical modelling\n * there is: an object that rings is a bank of resonators, so build the\n * bank. Each mode is a frequency ratio against the fundamental, a gain,\n * and its own decay time, and a struck object is that bank hit with a\n * short burst.\n *\n * A bell is the case that makes the method obvious, because a bell's\n * partials are not harmonic and cannot be produced by any oscillator that\n * assumes they are. The shipped bell material is 1, 2, 2.4, 3, 4.5, 5.33.\n * That 2.4 is the \"minor third\" partial that gives a large bell its\n * unsettled quality, and it is not 2.5 or 2.25 or anything a harmonic\n * series contains. Change it to 2.5 and the bell becomes a chime.\n *\n * Per mode decay is what makes it sound struck rather than played. The\n * fundamental rings for the full decay time and the upper modes fade at\n * 0.8, 0.7, 0.55 of it, so the sound gets purer as it dies. An object\n * whose partials all decayed together would sound like a filtered\n * oscillator.\n *\n * strike_hardness is the excitation, and it is the mallet. Soft misses the\n * upper modes entirely; hard puts energy into all of them at once.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/modal.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace bells {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 0.80f;\n\ninline constexpr player::Kind kKind = player::Kind::kMelody;\ninline constexpr int kVoices = 3;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Modal::Params p;\n    p.material = 2.0f;         /* bell: 1, 2, 2.4, 3, 4.5, 5.33 */\n    p.decay = 4.5f;\n    p.brightness = 0.62f;\n    p.strike_hardness = 0.7f;  /* a hard mallet, so the upper modes speak */\n    p.level = 0.55f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, rng, p);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::Modal, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace bells\n";

export const marimba_h: string = "/* 20_Instruments patch: marimba.\n *\n * The same engine as bells.h with one number changed, and that is the\n * argument for modal synthesis in a sentence. Material 4 is wood: five\n * modes at 1, 2.572, 4.644, 6.984, 9.723, and a decay_base of 0.12\n * against the bell's 1.8.\n *\n * Fifteen times shorter is not a tweak, it is the difference between metal\n * and wood. Metal is stiff and lossless and rings for seconds; a wooden bar\n * dumps its energy into the air and into whatever it is resting on, so it\n * is over in a couple of hundred milliseconds. Everything else people\n * describe as the \"warmth\" of a marimba follows from that plus the upper\n * modes dying faster still: 0.35, 0.18, 0.1 of an already short base, so\n * within one note it becomes almost a sine.\n *\n * Compare this file against bells.h and glass.h side by side. Three\n * instruments, one engine, and what separates them is a table of ratios\n * and decay times that lives in engines/modal.h and costs nothing per\n * voice.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/modal.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace marimba {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 3.40f;\n\ninline constexpr player::Kind kKind = player::Kind::kMelody;\ninline constexpr int kVoices = 3;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Modal::Params p;\n    p.material = 4.0f;         /* wood: fast, and faster in the upper modes */\n    p.decay = 2.4f;\n    p.brightness = 0.5f;\n    p.strike_hardness = 0.62f;  /* a mallet with some weight behind it */\n    p.level = 1.0f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, rng, p);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::Modal, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace marimba\n";

export const glass_h: string = "/* 20_Instruments patch: glass.\n *\n * The third material, and the one that shows what the decay table is for.\n * Glass is 1, 2.32, 4.25, 6.63, 9.38: sparse, widely spaced, and nearly\n * undamped up high. Its upper modes hold 0.75, 0.5, 0.35 of the base\n * decay, where wood's hold 0.35, 0.18, 0.1.\n *\n * That is the whole difference between a wine glass and a marimba bar and\n * it is four numbers. A glass keeps its brightness most of the way through\n * the note, which is why a rubbed rim sings a clean high tone and a struck\n * bar cannot.\n *\n * Sparse partials are also why this reads as a pitched instrument at all\n * despite being inharmonic. Five modes with big gaps between them do not\n * fuse into a single perceived pitch the way a harmonic series does; you\n * hear the fundamental and then you hear the others as ringing. Give it a\n * long decay and a light strike and it becomes an ambient texture rather\n * than a note, which is what this patch is set for.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/modal.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace glass {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 1.22f;\n\ninline constexpr player::Kind kKind = player::Kind::kMelody;\ninline constexpr int kVoices = 3;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Modal::Params p;\n    p.material = 3.0f;         /* glass: sparse, and it keeps its top */\n    p.decay = 6.0f;\n    p.brightness = 0.8f;\n    p.strike_hardness = 0.5f;  /* struck, not stroked, so it speaks at all */\n    p.level = 0.9f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, rng, p);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::Modal, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace glass\n";

export const clarinet_h: string = "/* 20_Instruments patch: clarinet.\n *\n * A waveguide, which is the other family of physical model. The string in\n * guitar.h is a delay line excited once and left to decay; a wind\n * instrument is a delay line driven CONTINUOUSLY by a nonlinear element at\n * one end, and that difference is the whole of why one dies away and the\n * other holds a note for as long as you have breath.\n *\n * The nonlinear element is the reed. Breath pressure pushes it toward the\n * mouthpiece, the pressure wave returning up the bore pushes it back, and\n * the reed's response to that sum is a curve rather than a line. A linear\n * reed would just move air. The curve is what turns steady pressure into\n * oscillation, and it is the same mechanism as a bow on a string.\n *\n * A clarinet is a cylinder closed at the reed, which is why it produces\n * mainly ODD harmonics and why it sounds hollow rather than bright. That\n * falls out of the tube geometry here rather than being filtered in.\n *\n * `breath` is the knob to turn and it is not a volume. Below a threshold\n * the reed never starts and you get air; just above it the tone is pure\n * and quiet; push it and the reed slams and the sound gets raucous. Real\n * players call that last part overblowing.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/tube.h\"\n\n#include \"player.h\"\n\nnamespace clarinet {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 0.41f;\n\ninline constexpr player::Kind kKind = player::Kind::kMelody;\n\nusing Bore = bellows::Tube<110>;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    Bore::Params p;\n    p.breath = 0.82f;   /* over the threshold, under the slam */\n    p.noise = 0.09f;    /* the air you hear around the tone */\n    p.level = 0.6f;\n    p.glide = 0.02f;\n    voice_.Init(sample_rate, rng, p);\n  }\n\n  /* Monophonic, as the instrument is: one bore, one note. */\n  void NoteOn(int, float hz, float vel) { voice_.NoteOn(hz, vel); }\n  void NoteOff(int) { voice_.NoteOff(); }\n\n  void operator()(float* l, float* r, int from, int to) { voice_.Process(l, r, from, to); }\n\n private:\n  Bore voice_;\n};\n\n}  // namespace clarinet\n";

export const choir_h: string = "/* 20_Instruments patch: vowel choir.\n *\n * Formant synthesis. What makes a sung \"ah\" different from a sung \"ee\" is\n * not the pitch and not the waveform: it is which frequency BANDS are\n * loud, and those bands stay where they are when the pitch moves. That is\n * the definition of a formant and it is why you can recognise a vowel sung\n * high or low by the same voice.\n *\n * So the model is a buzzy source through a bank of fixed resonators. The\n * tables here are the bass register measurements from Csound's standard\n * formant data, five vowels by five formants, each with a frequency, a\n * bandwidth and a level.\n *\n * The vowel parameter morphs continuously between adjacent vowels, and\n * HOW it morphs is the part worth knowing: frequency interpolates in the\n * log domain and bandwidth linearly. Interpolating frequency linearly\n * walks through pitches that are not between the two vowels in any way a\n * listener agrees with, because hearing is logarithmic. Getting that wrong\n * is the difference between a vowel gliding and a filter sweeping.\n *\n * Vibrato is what stops it sounding like a machine, and it is drawn from\n * the rng at note-on rather than per sample so a retrigger cannot\n * diverge from the browser's stream.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/formant.h\"\n#include \"bellows/voicepool.h\"\n\n#include \"player.h\"\n\nnamespace choir {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 1.30f;\n\ninline constexpr player::Kind kKind = player::Kind::kChord;\ninline constexpr int kVoices = 3;\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Formant::Params p;\n    p.vowel = 0.6f;           /* between \"a\" and \"e\" */\n    p.breath = 0.14f;\n    p.vibrato_rate = 4.6f;\n    p.vibrato_depth = 0.3f;\n    p.shape = 0.35f;\n    p.level = 0.55f;\n    for (int i = 0; i < kVoices; ++i) pool_.at(i).Init(sample_rate, rng, p);\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<bellows::Formant, kVoices> pool_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace choir\n";

export const eightoheight_h: string = "/* 20_Instruments patch: the long-decay drum machine kit.\n *\n * 02_DrumMachine already shows the Bank and the euclidean patterns. This\n * one is here for the sound rather than the architecture, and for one\n * number in particular.\n *\n * The famous analogue kick is a bridged-T oscillator that is only just\n * damped enough to stop, so it rings for the best part of a second and\n * spends most of that time below 60 Hz. Everything people say about that\n * machine having \"weight\" is that decay figure. Take it from 0.4 to 1.1\n * and the same synthesis is a different instrument. It is also the one\n * setting most likely to disappear entirely on a small speaker or a piezo,\n * which is why 15_Piezo throws away everything under 1.2 kHz rather than\n * pretending.\n *\n * The pitch sweep is the other half. A drum head's tension drops as it\n * moves, so the pitch falls fast at the start of the hit; pitch_decay is\n * how fast, and short values give the click that lets a kick cut through\n * on a small speaker even when the body of it is inaudible there.\n *\n * The snare is noise plus two detuned tones, and `tone` balances them. The\n * hat is six square oscillators at inharmonic ratios through a highpass,\n * which is the standard trick and sounds nothing like noise because the\n * ratios are fixed rather than random.\n *\n * The kit tunes from the noteOn frequency, so it is playable up and down\n * the keyboard rather than being three fixed samples.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/drums.h\"\n\n#include \"player.h\"\n\nnamespace eightoheight {\n\n/* Output trim, measured rather than guessed.\n *\n * The engines have no common loudness reference and nothing forces them to\n * agree: a struck wooden bar and a sustained reed are 30 dB apart on the\n * same settings, and an untrimmed patch library is one where changing\n * instrument means reaching for the volume. This number brings the patch to\n * the same RMS as the others through the shell's fader, taken from an\n * offline render of the actual part it plays. The master limiter catches\n * what is left, which on the plucked and struck patches is the transient. */\ninline constexpr float kTrim = 0.29f;\n\ninline constexpr player::Kind kKind = player::Kind::kPercussion;\n\n/* Pad indices, in the order the player fires them. */\nenum Pad { kKick = 0, kSnare, kHat, kPadCount };\n\nclass Patch {\n public:\n  void Init(float sample_rate, bellows::Rng* rng) {\n    bellows::Kick::Params k;\n    k.click_tune = 7.0f;\n    k.pitch_decay = 0.045f;  /* the click, and how fast the head detunes */\n    k.decay = 1.1f;          /* the whole argument of this patch */\n    k.drive = 2.6f;\n    kick_.Init(sample_rate, k);\n\n    bellows::Snare::Params s;\n    s.tone = 0.36f;          /* toward the noise rather than the shells */\n    s.decay = 0.24f;\n    s.snap = 0.22f;\n    snare_.Init(sample_rate, rng, s);\n\n    bellows::Hat::Params h;\n    h.decay = 0.055f;        /* closed. Open is anything past about 0.25 */\n    h.tone = 1.0f;\n    hat_.Init(sample_rate, h);\n  }\n\n  /* Pitched by pad rather than by note, which is what a kit is. The\n   * frequency is the tuning, so these are not fixed samples. */\n  void NoteOn(int pad, float, float vel) {\n    switch (pad) {\n      case kKick: kick_.NoteOn(48.0f, vel); break;\n      case kSnare: snare_.NoteOn(185.0f, vel); break;\n      case kHat: hat_.NoteOn(330.0f, vel); break;\n      default: break;\n    }\n  }\n\n  void NoteOff(int) {}\n\n  void operator()(float* l, float* r, int from, int to) {\n    kick_.Process(l, r, from, to);\n    snare_.Process(l, r, from, to);\n    hat_.Process(l, r, from, to);\n  }\n\n private:\n  bellows::Kick kick_;\n  bellows::Snare snare_;\n  bellows::Hat hat_;\n};\n\n}  // namespace eightoheight\n";

export const wspiezo_ino: string = "/*\n * 16_WorkstationPiezo: 07_Workstation through a piezo disc.\n *\n * The workstation patch unchanged, wrapped in the 15_Piezo voicing chain\n * and sent to MQS on pins 10 and 12.\n *\n * WIRING\n *   Teensy 4.x: pin 10 ---[ piezo disc ]--- pin 12\n *   Teensy 3.x: pin  6 ---[ piezo disc ]--- pin  9\n *\n *   Across the two pins, NOT from a pin to ground. Voiced renders the\n *   signal on one channel and its exact inverse on the other, so the disc\n *   sees 6.6 V peak to peak instead of 3.3. That is 6 dB for free.\n *   To ground works and is 6 dB quieter; nothing breaks either way.\n *\n * WHAT TO EXPECT, because the physics is not negotiable\n *   The voicing removes everything below 1.2 kHz, because a 27 mm disc is\n *   about a megaohm at 100 Hz and passes essentially nothing there. The\n *   workstation's kick is at 50 Hz and its bass line runs 110 to 262 Hz,\n *   so on a disc you will hear almost none of either. What is left is the\n *   hat, the snare's noise, and the upper partials of the plucked melody,\n *   which sits at 440 to 1397 Hz and therefore speaks mostly through its\n *   harmonics.\n *\n *   That is the disc, not the patch, and the fix is gain rather than\n *   arrangement: see kDrive below, which was worth 12 dB where moving the\n *   notes was worth less than nothing.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"../07_Workstation/workstation.h\"\n#include \"../15_Piezo/piezo.h\"\n\n/*\n * Drive into the limiter, and it is the only control here that changed\n * the loudness at all.\n *\n * Measured through this exact chain, as energy above 2 kHz, which is what\n * a disc turns into sound rather than broadband RMS:\n *\n *   drive  1   -33.7 dB     the limiter never engages once\n *   drive  4   -24.8 dB\n *   drive  8   -22.6 dB\n *   drive 12   -21.5 dB\n *   drive 16   -20.7 dB     +13 dB, and limiting hard\n *\n * Two things that sounded obvious and measured as wrong. Transposing the\n * piece up an octave to put its fundamentals nearer the disc's resonance\n * made it QUIETER, by 1.1 dB at +1 and 2.2 dB at +2, because a plucked\n * string carries less energy and decays faster the higher it is pitched.\n * And moving the highpass around barely mattered: 800 Hz to 3200 Hz spans\n * 0.7 dB in the radiated band, so the 1200 Hz default is already doing its\n * job and the bass was never the thing holding the level down.\n */\nstatic constexpr float kDrive = 12.0f;\n\nstatic workstation::Piece piece;\nstatic piezo::Voiced<workstation::Piece> voiced(piece);\nstatic bellows::BellowsAudioStream<piezo::Voiced<workstation::Piece>> node(voiced);\n\n/* MQS: Medium Quality Sound, pins 10 and 12, no external parts at all. A\n * sigma-delta output filtered by the disc itself, which for a transducer\n * that rolls off above its resonance is a better match than it sounds. */\n#if defined(__IMXRT1062__)\n/* MQS on pins 10 and 12, Teensy 4.x only. */\nstatic AudioOutputMQS out;\n#else\n/* PWM on pins 6 and 9. Same reasoning as 15_Piezo: driving a disc you can\n * usually omit the RC filter, because the disc's own capacitance and its\n * rolloff do the filtering and there is nothing downstream to offend.\n *\n * Without this the sketch named a 4.x-only class unconditionally and the\n * 3.x builds came back \"failed\" rather than \"does not fit\", which reads\n * like a defect in the library and was a missing #if here. */\nstatic AudioOutputPWM out;\n#endif\n\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  Serial.begin(115200);\n\n  const float sr = bellows::TeensySampleRate();\n  piece.Init(sr, 96);\n\n  piezo::Voicing v;\n  /* Measure yours: 15_Piezo has a sweep mode that steps a tone across the\n   * band so you can hear which frequency is loudest. This is the default\n   * for a bare 27 mm brass disc. Mounting it lowers the resonance. */\n  v.resonance_hz = 4000.0f;\n  v.drive = kDrive;\n  voiced.Init(sr, v);\n\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(24);\n  if (!piece.Trained()) Serial.println(\"workstation: markov table full, melody is truncated\");\n  Serial.println(\"07_Workstation -> piezo on pins 10 and 12\");\n  Serial.print(\"sample rate \");\n  Serial.println(sr);\n}\n\nvoid loop() {\n  /* The sequencer runs inside the audio callback, so the loop only\n   * reports. AudioProcessorUsageMax is the number Milestone 1 exists to\n   * collect, and this is the heaviest sketch in the set. */\n  delay(2000);\n  Serial.print(\"bar \");\n  Serial.print(piece.Bar() + 1);\n  Serial.print(\"/4  voices \");\n  Serial.print(piece.Voices());\n  Serial.print(\"  cpu \");\n  Serial.print(AudioProcessorUsage(), 1);\n  Serial.print(\"%  peak \");\n  Serial.print(AudioProcessorUsageMax(), 1);\n  Serial.print(\"%  mem \");\n  Serial.print(AudioMemoryUsageMax());\n  Serial.println();\n}\n";

export const wsi2s_ino: string = "/*\n * 17_WorkstationI2S: 07_Workstation into an I2S amplifier, summed to mono.\n *\n * The full patch this time, with nothing filtered out. 16_WorkstationPiezo\n * had to throw away everything below 1.2 kHz because a disc cannot\n * reproduce it; a MAX98357A driving a speaker can, so the kick at 50 Hz\n * and the bass line at 110 to 262 Hz come back.\n *\n * WIRING (Teensy 4.0)\n *   Teensy 7  (OUT1A / TX)  -> DIN\n *   Teensy 21 (BCLK)        -> BCLK\n *   Teensy 20 (LRCLK)       -> LRC\n *   Teensy 5V (VIN pin)     -> VIN\n *   Teensy GND              -> GND\n *   speaker across the breakout's + and -\n *\n *   Power from 5V and not from the Teensy's 3.3V regulator. A MAX98357A is\n *   a 3W amplifier and at real volume it pulls far more than that\n *   regulator wants to give. A brownout does not look like a power\n *   problem, it looks like the audio glitching on loud notes.\n *\n *   No MCLK and no I2C. The breakout has no control interface, which is\n *   why there is no codec object here and nothing to enable: the level in\n *   the patch is the level you get.\n *\n * WHY THIS SUMS TO MONO ITSELF\n *\n * The amplifier is mono and its SD pin picks what it does with the two\n * channels: average them, or take left, or take right, according to the\n * voltage on it. The Adafruit board carries a 1M pullup there, and which\n * of those three that lands on is exactly the sort of thing worth not\n * guessing about.\n *\n * So this renders the same signal on both channels. Then every SD setting\n * gives the same result and the pin stops mattering. It also removes the\n * failure that firmware built for a piezo would hit here: the piezo chain\n * ends with r = -l, deliberately, to double the swing across a disc, and\n * an amplifier that averages L and R would sum that to exact silence.\n *\n * The cost is the stereo image, which is the delay send's cross-feed and\n * nothing else in this patch. On one speaker there was no image anyway.\n *\n * A NEW PIECE EVERY TIME IT POWERS UP\n *\n * Piece::Compose(seed) redraws the arrangement rather than just the dice:\n * the mode, the four bar progression, all five euclidean rhythms, the\n * motif the Markov chain trains on, and the tempo. So two boots are two\n * pieces, not one piece played twice with different noise.\n *\n * The seed still decides everything, which is the library's whole promise,\n * so it is printed. Write down a number you liked and put it in kPinnedSeed\n * to hear that piece again.\n *\n * Getting the number off the board is fussier than it sounds and it used to\n * be impossible. A host cannot open the USB serial port before setup() has\n * run, and a Teensy throws output away when nothing is listening, so the\n * startup banner was reliably lost and the seed with it. Two things fix it:\n * setup() waits up to two seconds for a listener before printing, and the\n * periodic report carries the seed as well, so a console attached at any\n * point in the piece still shows it.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"../07_Workstation/workstation.h\"\n\n/* 0 draws a fresh seed at power up. Set it to a number the sketch printed\n * to play that arrangement again. */\nstatic constexpr uint32_t kPinnedSeed = 0;\n\nstatic workstation::Piece piece;\n\n/* Set by setup() and read by loop(), which reprints it every two seconds. */\nstatic uint32_t composed_seed = 0;\n\n/*\n * A seed that differs every time the board powers up.\n *\n * There is no real entropy source here worth the name. A Teensy 4.0 has no\n * battery-backed clock unless you fit one, so time starts at the same\n * place on every boot, and the cycle counter at the top of setup() is very\n * nearly deterministic for the same reason.\n *\n * What is genuinely noisy is an unconnected analog pin: the bottom bits of\n * a floating ADC read are thermal and pickup noise rather than a value.\n * A0 to A3 are pins 14 to 17 and are free here. Deliberately NOT A6 and\n * A7, which are pins 20 and 21, because those are carrying LRCLK and BCLK\n * to the amplifier.\n *\n * This mixes 64 of those reads with the cycle counter through an FNV\n * step. It is good enough to make two power ups different, which is all it\n * is for. It is not random in any sense worth defending, and nothing here\n * should be used to make a decision that matters.\n */\nstatic uint32_t BootSeed() {\n  uint32_t h = 2166136261u;\n  for (int i = 0; i < 64; ++i) {\n    const int a = analogRead(A0 + (i & 3));\n    h ^= static_cast<uint32_t>(a) & 0x0fu;\n    h *= 16777619u;\n    h ^= ARM_DWT_CYCCNT;\n    h *= 16777619u;\n    delayMicroseconds(97);\n  }\n  /* 0 means \"draw one\" to the caller, so never hand back 0. */\n  return h == 0u ? 1u : h;\n}\n\n/* Renders the piece, then folds it down. Same signature, so it drops\n * straight into BellowsAudioStream in place of the patch it wraps. */\nstruct Mono {\n  void operator()(float* l, float* r, int from, int to) {\n    piece(l, r, from, to);\n    for (int i = from; i < to; ++i) {\n      const float m = 0.5f * (l[i] + r[i]);\n      l[i] = m;\n      r[i] = m;\n    }\n  }\n};\n\nstatic Mono mono;\nstatic bellows::BellowsAudioStream<Mono> node(mono);\n\n/* No AudioControlSGTL5000 and no codec.enable(). That absence is the whole\n * difference between this and the audio shield sketch. */\nstatic AudioOutputI2S out;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  Serial.begin(115200);\n  /* Five parts and a send bus is more work per callback than one voice. */\n  const float sr = bellows::TeensySampleRate();\n  piece.Init(sr, 96);\n\n  composed_seed = kPinnedSeed != 0u ? kPinnedSeed : BootSeed();\n  piece.Compose(composed_seed);\n\n  /* AudioMemory LAST, and this ordering is load bearing.\n   *\n   * BellowsAudioStream::update() returns early only while allocate() is\n   * null, which is to say only until AudioMemory() runs. After that the\n   * audio interrupt renders whatever it is pointed at, so anything\n   * initialised below this line can be rendered before it is ready. A\n   * delay line that has not been given its buffer reads through a null\n   * pointer, which on an IMXRT1062 is executable memory rather than a\n   * trap page. */\n  AudioMemory(24);\n\n  /* Wait for a console, but not forever: the board has to run standalone.\n   * Serial is true once the host asserts DTR, which is what opening the port\n   * does. Two seconds is long enough to catch a console that was already\n   * open, and short enough that a board on a battery just plays. The audio\n   * is already running by here, so the wait costs nothing but the banner. */\n  while (!Serial && millis() < 2000) {\n  }\n\n  if (!piece.Trained()) Serial.println(\"workstation: markov table full, melody is truncated\");\n  Serial.println(\"07_Workstation -> I2S amp, summed to mono\");\n  Serial.print(\"sample rate \");\n  Serial.println(sr);\n  Serial.print(\"seed \");\n  Serial.print(composed_seed);\n  Serial.println(\"   put this in kPinnedSeed to hear it again\");\n}\n\nvoid loop() {\n  /* The sequencer runs inside the audio callback, so the loop only\n   * reports. AudioProcessorUsageMax is the number Milestone 1 exists to\n   * collect, and this is the heaviest sketch in the set. */\n  delay(2000);\n  Serial.print(\"bar \");\n  Serial.print(piece.Bar() + 1);\n  Serial.print(\"/4  voices \");\n  Serial.print(piece.Voices());\n  Serial.print(\"  cpu \");\n  Serial.print(AudioProcessorUsage(), 1);\n  Serial.print(\"%  peak \");\n  Serial.print(AudioProcessorUsageMax(), 1);\n  Serial.print(\"%  mem \");\n  Serial.print(AudioMemoryUsageMax());\n  Serial.print(\"  seed \");\n  Serial.print(composed_seed);\n  Serial.println();\n}\n";

export const presets_h: string = "/* Shared logic for the 21_Presets example: the whole preset table, played.\n *\n * 20_Instruments is eleven patches written out by hand, one header each.\n * This is the other half of the same idea: bellows/presets/instruments.h\n * already holds all 50 presets as data, so the program here is the shell\n * that turns a row of that table into a sounding voice, and it is short\n * because the table does the describing.\n *\n * HOW A ROW BECOMES A VOICE\n *\n * The table splits a preset into an engine tag, a slot, and a params row\n * in that engine's own table, because no single struct can hold eleven\n * different Params. So the shell needs one voice pool per engine, and a\n * way to send a preset to the right one. That is bellows::Bank, indexed by\n * the engine tag itself:\n *\n *   book_.With(pre.engine, [&](auto& slot) { slot.Load(pre); });\n *\n * Bank::With is a chain of integer compares resolved at the call site, so\n * the dispatch is the same shape a registry would give and costs no\n * vtable, no string and no allocation. Each Slot then asks the table for\n * ITS params (PluckParamsOf returns nullptr for a modal preset) and\n * applies them into its own engine's Params, where the field names are\n * checked by the compiler.\n *\n * Loading re-Inits the pool rather than calling SetParams, because Pluck\n * has no SetParams: its loop filter and delay length are derived at Init.\n * Re-Init is free here, since a preset only changes between phrases.\n *\n * ELEVEN ENGINES IN ONE IMAGE, WHICH IS THE HONEST WAY TO SIZE IT\n *\n * This sketch names every engine the table uses, so all eleven are linked,\n * and the size it reports is the whole book rather than the cheapest\n * preset in it. A sketch that only wanted the mallets would name\n * kEngineModal's slot and nothing else, and --gc-sections would drop the\n * other ten engines and their ten param tables. That property is the\n * reason the preset table is split the way it is, and it is only worth\n * anything if nobody has to take it on faith: build this, then build it\n * with the Bank cut down to one slot, and compare.\n *\n * WHAT IS PLAYED\n *\n * The same four bars for every preset, in A natural minor through the\n * tuning layer, alternating: a broken line, then a held triad, twice. One\n * part rather than 20_Instruments' four, because the question here is what\n * the preset table sounds like, not what part suits a clarinet. A pad gets\n * an arpeggio it would not have chosen and a woodblock gets a held chord\n * it cannot sustain, and both are informative.\n *\n * LEVELS ARE NOT MATCHED, AND THE TABLE DOES NOT CLAIM THEY ARE\n *\n * Each preset carries a gain trim from the JS, mostly 0.8, and that is a\n * channel trim someone chose in a browser, not a measured loudness match\n * like 20_Instruments' kTrim. The engines have no common loudness\n * reference, so a struck bar and a sustained reed are far apart on the\n * same numbers, and stepping through the tour means the level moves. The\n * master limiter keeps the peaks in bounds and nothing here pretends to\n * fix the rest.\n *\n * clean-electric asks for a tape delay, which is not ported, so it plays\n * dry. The table says so through kFxTapeDelay rather than quietly\n * substituting the clean delay, and this shell prints it.\n *\n * WHERE THE RAM GOES\n *\n * Three inserts are instantiated once and shared, because only one preset\n * sounds at a time. Two of them are small; the plate is not. Plate<48000,\n * 30> is a 30 ms predelay ceiling, which is all the four string presets\n * ask for (25 ms at the cello and the double bass), and its tank is still\n * the largest single object in the sketch. A preset tour that never\n * selects a string preset does not need it, and cutting it is the first\n * thing to try if this has to fit somewhere smaller. The second is the\n * Pluck and Waveguide pools, which are sized for a 55 Hz floor because\n * bass-guitar and double-bass are shifted two octaves down.\n */\n#pragma once\n\n#include <stdint.h>\n\n#include \"bellows/bank.h\"\n#include \"bellows/config.h\"\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/additive.h\"\n#include \"bellows/engines/fm.h\"\n#include \"bellows/engines/formant.h\"\n#include \"bellows/engines/harmonic.h\"\n#include \"bellows/engines/modal.h\"\n#include \"bellows/engines/pluck.h\"\n#include \"bellows/engines/tube.h\"\n#include \"bellows/engines/va.h\"\n#include \"bellows/engines/waveguide.h\"\n#include \"bellows/engines/wavetable.h\"\n#include \"bellows/engines/westcoast.h\"\n#include \"bellows/fx/dynamics.h\"\n#include \"bellows/fx/modfx.h\"\n#include \"bellows/fx/plate.h\"\n#include \"bellows/presets/instruments.h\"\n#include \"bellows/theory/scales.h\"\n#include \"bellows/theory/tuning.h\"\n#include \"bellows/voicepool.h\"\n\nnamespace presets {\n\n/* ------------------------------------------------------------------ */\n/* The part                                                             */\n/* ------------------------------------------------------------------ */\n\ninline constexpr int kSteps = 16; /* sixteenths in a bar */\ninline constexpr int kBars = 4;\n\n/* Degrees of the scale, relative to the root. kRest is outside any degree\n * the scale can produce. */\ninline constexpr int kRest = -99;\ninline constexpr int kLine[kSteps] = {0, kRest, 4,     kRest, 2,     kRest, 7,     kRest,\n                                      4, kRest, 2,     kRest, 0,     kRest, kRest, kRest};\n\n/* The held triad, in degrees. Three notes is also the polyphony every\n * pool below is sized for. */\ninline constexpr int kTriad[3] = {0, 2, 4};\n\n/* Step the triad is released on, leaving four sixteenths of tail before\n * the bar turns over. */\ninline constexpr int kChordRelease = 12;\n\n/* A3 in 12-EDO. The line reaches degree 7, an octave up, and the preset's\n * own octave shift moves the lot: bass-guitar at -2 puts the root on 55 Hz,\n * which is why the Pluck below is sized for 55 and not for 110. */\ninline constexpr int kRootIndex = 57;\n\n/* ------------------------------------------------------------------ */\n/* One engine's voices                                                  */\n/* ------------------------------------------------------------------ */\n\n/*\n * Engines do not agree on how they are initialised: Pluck, Modal, Va,\n * Tube, Formant and Harmonic take an Rng, Waveguide takes two, and Fm,\n * WestCoast, Additive and Wavetable take none, because only some of them\n * have noise in them. Rather than detect that, each traits struct below\n * writes the call out. Eleven lines of explicitness beats a SFINAE probe\n * that fails to read.\n *\n * The second Rng Waveguide wants is the JS rng.fork('note') stream, which\n * per note jitter and the pitch settle draw from so they never shift the\n * main stream. Fork is string concatenation, so the label is the parent's\n * plus \"::note\".\n *\n * Voice counts are three everywhere, which is what the held triad needs.\n * The two waveguides are the expensive ones. Pluck at a 55 Hz floor is 876\n * samples of delay plus twice that of excitation table, 10.5 KB a voice,\n * 31.5 KB for the pool. Waveguide at the same floor is three delay lines,\n * about 11.3 KB a voice and 34 KB for the pool, and it is 55 Hz for the\n * same reason: double-bass is shifted two octaves down. Tube at a 110 Hz\n * floor is a bore half period, an order of magnitude less. Those are the\n * numbers to cut first if this has to fit somewhere smaller.\n */\ninline constexpr int kVoices = 3;\n\nstruct PluckTraits {\n  using Engine = bellows::Pluck<55>;\n  using Data = bellows::PluckPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) { return bellows::PluckParamsOf(p); }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng*,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, p);\n  }\n};\n\nstruct ModalTraits {\n  using Engine = bellows::Modal;\n  using Data = bellows::ModalPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) { return bellows::ModalParamsOf(p); }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng*,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, p);\n  }\n};\n\nstruct VaTraits {\n  using Engine = bellows::Va;\n  using Data = bellows::VaPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) { return bellows::VaParamsOf(p); }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng*,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, p);\n  }\n};\n\nstruct FmTraits {\n  using Engine = bellows::Fm;\n  using Data = bellows::FmPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) { return bellows::FmParamsOf(p); }\n  static void Init(Engine& v, float sr, bellows::Rng*, bellows::Rng*, const Engine::Params& p) {\n    v.Init(sr, p);\n  }\n};\n\nstruct TubeTraits {\n  using Engine = bellows::Tube<110>;\n  using Data = bellows::TubePresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) { return bellows::TubeParamsOf(p); }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng*,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, p);\n  }\n};\n\nstruct FormantTraits {\n  using Engine = bellows::Formant;\n  using Data = bellows::FormantPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) {\n    return bellows::FormantParamsOf(p);\n  }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng*,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, p);\n  }\n};\n\nstruct WestCoastTraits {\n  using Engine = bellows::WestCoast;\n  using Data = bellows::WestCoastPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) {\n    return bellows::WestCoastParamsOf(p);\n  }\n  static void Init(Engine& v, float sr, bellows::Rng*, bellows::Rng*, const Engine::Params& p) {\n    v.Init(sr, p);\n  }\n};\n\n/* The bowed waveguide. The second polarization stays compiled in, since\n * the four bowed presets set polDetune and the engine switches it off by\n * itself when the value is 0, which is what pizzicato-strings gets. */\nstruct StringTraits {\n  using Engine = bellows::Waveguide<55>;\n  using Data = bellows::StringPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) { return bellows::StringParamsOf(p); }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng* note_rng,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, note_rng, p);\n  }\n};\n\nstruct HarmonicTraits {\n  using Engine = bellows::Harmonic;\n  using Data = bellows::HarmonicPresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) {\n    return bellows::HarmonicParamsOf(p);\n  }\n  static void Init(Engine& v, float sr, bellows::Rng* rng, bellows::Rng*,\n                   const Engine::Params& p) {\n    v.Init(sr, rng, p);\n  }\n};\n\nstruct AdditiveTraits {\n  using Engine = bellows::Additive<>;\n  using Data = bellows::AdditivePresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) {\n    return bellows::AdditiveParamsOf(p);\n  }\n  static void Init(Engine& v, float sr, bellows::Rng*, bellows::Rng*, const Engine::Params& p) {\n    v.Init(sr, p);\n  }\n};\n\nstruct WavetableTraits {\n  using Engine = bellows::Wavetable;\n  using Data = bellows::WavetablePresetParams;\n  static const Data* Find(const bellows::InstrumentPreset& p) {\n    return bellows::WavetableParamsOf(p);\n  }\n  static void Init(Engine& v, float sr, bellows::Rng*, bellows::Rng*, const Engine::Params& p) {\n    v.Init(sr, p);\n  }\n};\n\n/* A pool of one engine, plus the two calls the shell makes on it. */\ntemplate <class T>\nclass Slot {\n public:\n  void Init(float sample_rate, bellows::Rng* rng, bellows::Rng* note_rng) {\n    sr_ = sample_rate;\n    rng_ = rng;\n    note_rng_ = note_rng;\n    typename T::Engine::Params p; /* engine defaults until a preset lands */\n    for (int i = 0; i < kVoices; ++i) T::Init(pool_.at(i), sr_, rng_, note_rng_, p);\n  }\n\n  /* False when the preset belongs to another engine, which is how the\n   * Bank's other ten slots answer. */\n  bool Load(const bellows::InstrumentPreset& pre) {\n    const typename T::Data* d = T::Find(pre);\n    if (d == nullptr) return false;\n    typename T::Engine::Params p;\n    bellows::ApplyPreset(*d, &p);\n    for (int i = 0; i < kVoices; ++i) T::Init(pool_.at(i), sr_, rng_, note_rng_, p);\n    return true;\n  }\n\n  void NoteOn(int id, float hz, float vel) { pool_.NoteOn(id, hz, vel, frame_); }\n  void NoteOff(int id) { pool_.NoteOff(id); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::VoicePool<typename T::Engine, kVoices> pool_;\n  bellows::Rng* rng_ = nullptr;\n  bellows::Rng* note_rng_ = nullptr;\n  float sr_ = BELLOWS_SAMPLE_RATE;\n  uint32_t frame_ = 0;\n};\n\n/* Declaration order IS bellows::PresetEngine order. The static_assert\n * below is what keeps it that way: get it wrong and a modal preset is\n * loaded into the pluck pool, which sounds like nothing at all. */\nusing Book =\n    bellows::Bank<Slot<PluckTraits>, Slot<ModalTraits>, Slot<VaTraits>, Slot<FmTraits>,\n                  Slot<TubeTraits>, Slot<FormantTraits>, Slot<WestCoastTraits>,\n                  Slot<StringTraits>, Slot<HarmonicTraits>, Slot<AdditiveTraits>,\n                  Slot<WavetableTraits>>;\n\nstatic_assert(Book::kCount == bellows::kPresetEngineCount,\n              \"the bank must have one slot per PresetEngine, in enum order\");\n\n/* ------------------------------------------------------------------ */\n/* The tour                                                             */\n/* ------------------------------------------------------------------ */\n\n/* 30 ms of predelay ceiling. The four string presets ask for 20 and 25,\n * and the default 250 would carry 193628 bytes of tank instead of the\n * 25352 this does. Nothing else in the table wants a plate. */\nusing PlateInsert = bellows::Plate<BELLOWS_SAMPLE_RATE, 30>;\n\nclass Tour {\n public:\n  void Init(float sample_rate, unsigned bpm = 96) {\n    sr_ = sample_rate;\n    rng_.Init(\"presets\");\n    note_rng_.Init(\"presets::note\");\n    scale_.Init(kRootIndex, bellows::kScaleMinor);\n    edo12_.InitEdo(12, 440.0f, 69);\n    book_.ForEach(\n        [this, sample_rate](auto& slot) { slot.Init(sample_rate, &rng_, &note_rng_); });\n\n    bellows::Chorus<>::Params ch; /* replaced per preset, never bypassed by params */\n    chorus_.Init(sample_rate, ch);\n    bellows::Tremolo::Params tr;\n    tremolo_.Init(sample_rate, tr, &rng_);\n    /* Init carves the tank out of the plate's own storage and answers\n     * false if the rate needs more than it was sized for. Nothing here can\n     * recover from that, so it is remembered and printed rather than\n     * ignored: a silent false would play the four string presets dry. */\n    PlateInsert::Params pl;\n    plate_ok_ = plate_.Init(sample_rate, pl);\n\n    /* A trim cannot fix a 30 dB crest factor on a plucked chord, so the\n     * peaks are caught here rather than by pulling every preset down to\n     * fit the loudest transient in the table. */\n    bellows::Limiter<>::Params lim;\n    lim.ceiling_db = -1.0f;\n    lim.release = 0.06f;\n    limiter_.Init(sample_rate, lim);\n\n    SetTempo(bpm);\n    Select(0);\n  }\n\n  void SetTempo(unsigned bpm) {\n    const float steps_per_sec = (static_cast<float>(bpm) / 60.0f) * 4.0f;\n    samples_per_step_ = static_cast<int>(sr_ / steps_per_sec + 0.5f);\n    if (samples_per_step_ < 1) samples_per_step_ = 1;\n  }\n\n  /* Load preset `i` from the table. Out of range wraps, so a caller can\n   * hand this a free running counter. */\n  void Select(int i) {\n    if (bellows::kInstrumentPresetCount <= 0) return;\n    i %= bellows::kInstrumentPresetCount;\n    if (i < 0) i += bellows::kInstrumentPresetCount;\n    /* Release whatever the outgoing preset holds first, or a pad sustains\n     * under the next instrument for the rest of the tour. */\n    AllOff();\n    which_ = i;\n    step_ = 0;\n    const bellows::InstrumentPreset& pre = bellows::kInstrumentPresets[which_];\n    /* Load answers false when the slot it landed on belongs to another\n     * engine, which can only happen if the Bank's declaration order stops\n     * matching PresetEngine. The count is checked at compile time and the\n     * order is checked here, because a preset loaded into the wrong pool\n     * plays the previous preset's params and has no other symptom. */\n    loaded_ = false;\n    book_.With(pre.engine, [this, &pre](auto& slot) { loaded_ = slot.Load(pre); });\n\n    if (const auto* c = bellows::ChorusParamsOf(pre)) {\n      bellows::Chorus<>::Params p;\n      bellows::ApplyPreset(*c, &p);\n      chorus_.SetParams(p);\n      chorus_.Reset();\n    }\n    if (const auto* t = bellows::TremoloParamsOf(pre)) {\n      bellows::Tremolo::Params p;\n      bellows::ApplyPreset(*t, &p);\n      tremolo_.SetParams(p);\n      tremolo_.Reset();\n    }\n    if (const auto* t = bellows::PlateParamsOf(pre)) {\n      PlateInsert::Params p;\n      bellows::ApplyPreset(*t, &p);\n      plate_.SetParams(p);\n      plate_.Reset();\n    }\n  }\n\n  int Selected() const { return which_; }\n  const bellows::InstrumentPreset& Current() const { return bellows::kInstrumentPresets[which_]; }\n  int Bar() const { return (step_ / kSteps) % kBars; }\n\n  /* False when the last Select found no pool for its engine. */\n  bool Loaded() const { return loaded_; }\n\n  /* False when the plate refused the sample rate, which would leave the\n   * four string presets dry. */\n  bool PlateReady() const { return plate_ok_; }\n\n  void operator()(float* l, float* r, int from, int to) {\n    int i = from;\n    while (i < to) {\n      if (countdown_ <= 0) {\n        Step();\n        countdown_ = samples_per_step_;\n      }\n      int span = to - i;\n      if (span > countdown_) span = countdown_;\n      if (span > kMaxBlock) span = kMaxBlock;\n\n      /* Voices ADD, so the preset is rendered into a scratch, run through\n       * its insert, trimmed, and only then added to the output. Rendering\n       * it straight into l and r would put the insert on everything that\n       * was there already. */\n      for (int k = 0; k < span; ++k) {\n        scratch_l_[k] = 0.0f;\n        scratch_r_[k] = 0.0f;\n      }\n      const bellows::InstrumentPreset& pre = Current();\n      book_.With(pre.engine, [this, span](auto& slot) { slot(scratch_l_, scratch_r_, 0, span); });\n      if (pre.fx == bellows::kFxChorus) chorus_.Process(scratch_l_, scratch_r_, 0, span);\n      if (pre.fx == bellows::kFxTremolo) tremolo_.Process(scratch_l_, scratch_r_, 0, span);\n      if (pre.fx == bellows::kFxPlate) plate_.Process(scratch_l_, scratch_r_, 0, span);\n      for (int k = 0; k < span; ++k) {\n        l[i + k] += pre.gain * scratch_l_[k];\n        r[i + k] += pre.gain * scratch_r_[k];\n      }\n      limiter_.Process(l, r, i, i + span);\n      i += span;\n      countdown_ -= span;\n    }\n  }\n\n private:\n  static constexpr int kMaxBlock = BELLOWS_BLOCK_SIZE;\n\n  /* Frequency of a degree, through the tuning layer, shifted by the\n   * preset's suggested octave. Nothing here writes 440 * 2^((n - 69) / 12):\n   * swap edo12_ for a 19-EDO tuning and the whole tour moves into it. */\n  float Hz(int degree) const {\n    float hz = bellows::DegreeFreq(edo12_, kRootIndex, scale_.Intervals(), scale_.Length(), degree);\n    for (int8_t o = Current().octave; o > 0; --o) hz *= 2.0f;\n    for (int8_t o = Current().octave; o < 0; ++o) hz *= 0.5f;\n    return hz;\n  }\n\n  void Step() {\n    const int s = step_ % kSteps;\n    const bool chord_bar = (Bar() % 2) == 1;\n\n    if (chord_bar) {\n      if (s == 0) {\n        AllOff();\n        for (int i = 0; i < 3; ++i) {\n          const int d = kTriad[i];\n          book_.With(Current().engine, [this, d](auto& slot) { slot.NoteOn(d, Hz(d), 0.62f); });\n          held_[i] = d;\n        }\n        held_count_ = 3;\n      } else if (s == kChordRelease) {\n        AllOff();\n      }\n    } else {\n      const int d = kLine[s];\n      if (d != kRest) {\n        /* No NoteOff for the line, as 20_Instruments' melody part does\n         * nothing either: a plucked string has no key to lift and its\n         * NoteOff is a palm mute, so the pool's steal order (free, then\n         * oldest released, then oldest held) ends the notes instead. On a\n         * sustaining preset that means three notes overlap.\n         *\n         * Accent the downbeats, which is what moves a filter or a\n         * wavefolder and does nothing at all to a struck bar. */\n        const float vel = (s % 4 == 0) ? 0.9f : 0.6f;\n        book_.With(Current().engine, [this, d, vel](auto& slot) { slot.NoteOn(d, Hz(d), vel); });\n      }\n    }\n    ++step_;\n  }\n\n  void AllOff() {\n    for (int i = 0; i < held_count_; ++i) {\n      const int id = held_[i];\n      book_.With(Current().engine, [id](auto& slot) { slot.NoteOff(id); });\n    }\n    held_count_ = 0;\n  }\n\n  Book book_;\n  bellows::Rng rng_;\n  bellows::Rng note_rng_;\n  bellows::Scale scale_;\n  bellows::Tuning12 edo12_;\n  bellows::Chorus<> chorus_;\n  bellows::Tremolo tremolo_;\n  PlateInsert plate_;\n  bellows::Limiter<> limiter_;\n  float scratch_l_[kMaxBlock] = {};\n  float scratch_r_[kMaxBlock] = {};\n  float sr_ = BELLOWS_SAMPLE_RATE;\n  int samples_per_step_ = 1;\n  int countdown_ = 0;\n  int step_ = 0;\n  int which_ = 0;\n  int held_[3] = {0, 0, 0};\n  int held_count_ = 0;\n  bool loaded_ = false;\n  bool plate_ok_ = false;\n};\n\n}  // namespace presets\n";

export const presets_ino: string = "/*\n * 21_Presets: the instrument preset table, played end to end.\n *\n * bellows/presets/instruments.h is the port of the TypeScript preset\n * library: all 50 named instruments as flash-resident data, no strings in\n * the audio path, no registry. This sketch walks it. Ten seconds each,\n * four bars of the same part every time, so what changes between them is\n * the instrument and nothing else.\n *\n * presets.h is the program. This file is the board.\n *\n * WHAT THIS EXAMPLE IS FOR\n *\n * 20_Instruments is eleven patches, each written out by hand in its own\n * header, and it is the better place to read how a patch is built. This\n * one is the argument that the preset table works: one shell, one part,\n * eleven engines, and every preset in the library reachable by index or by\n * id with no allocation and no lookup by string on the audio path.\n *\n * BOARDS\n *   Teensy 4.1 builds and links. Eleven engines and their voice pools in\n *   one image is the whole book rather than the cheapest preset in it: the\n *   Pluck pool is 31.5 KB and the Waveguide pool 34 KB, both because\n *   bass-guitar and double-bass shift two octaves down onto a 55 Hz floor,\n *   and the plate the four bowed presets ask for is 25 KB of tank. See the\n *   matrix in examples/README.md for the rest and note that fitting is not\n *   the same as keeping up: nothing here has been run on hardware.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack. For any other output see examples 11 to 15.\n *\n * WHAT IS VERIFIED\n *   The preset header compiles standalone for Cortex-M7, every value in it\n *   is diffed against the TypeScript by npm run presets:check, this sketch\n *   links as Teensy 4.1 firmware, and every one of the 50 presets was\n *   instantiated on the host and rendered for a second through this shell:\n *   all finite, all non-silent. Nothing here has been flashed to a board.\n *\n * PORTING\n *   To a Daisy Seed: swap bellows/platform/teensy.h for\n *   bellows/platform/daisy.h and start the audio through DaisyAudio<T>.\n *   presets.h does not change.\n */\n\n#include <Audio.h>\n\n#include <Bellows.h>\n#include \"bellows/platform/teensy.h\"\n#include \"presets.h\"\n\nstatic presets::Tour tour;\n\nstatic bellows::BellowsAudioStream<presets::Tour> node(tour);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  Serial.begin(115200);\n  codec.enable();\n  codec.volume(0.6f);\n  tour.Init(bellows::TeensySampleRate(), 96);\n  /* The plate carves its tank at Init and can refuse the rate. Said once\n   * here rather than on every string preset, and said at all because a\n   * refusal is otherwise four presets that sound a little dry. */\n  if (!tour.PlateReady()) Serial.println(\"plate did not init: the string presets will play dry\");\n\n  /* AudioMemory LAST: it is what opens the audio interrupt, and anything\n   * initialised after it can be rendered before it is ready. See the note\n   * in platform/teensy.h. */\n  AudioMemory(20);\n}\n\nvoid loop() {\n  for (int i = 0; i < bellows::kInstrumentPresetCount; ++i) {\n    tour.Select(i);\n    const bellows::InstrumentPreset& pre = tour.Current();\n\n    Serial.print(i + 1);\n    Serial.print(\"/\");\n    Serial.print(bellows::kInstrumentPresetCount);\n    Serial.print(\"  \");\n    Serial.print(pre.label);\n    Serial.print(\"  [\");\n    Serial.print(bellows::FamilyName(pre.family));\n    Serial.print(\"/\");\n    Serial.print(bellows::PresetEngineName(pre.engine));\n    Serial.print(\"]  gain \");\n    Serial.print(pre.gain, 2);\n    if (pre.octave != 0) {\n      Serial.print(\"  oct \");\n      Serial.print(pre.octave);\n    }\n    /* The one preset whose insert has no port. Saying so beats letting it\n     * sound thinner than the browser does for no stated reason. */\n    if (pre.fx == bellows::kFxTapeDelay) Serial.print(\"  (tape delay not ported, dry)\");\n    /* The one thing Select can get wrong, and it is silent otherwise: the\n     * bank's slot order has to be PresetEngine's order. */\n    if (!tour.Loaded()) Serial.print(\"  NOT LOADED, bank order does not match PresetEngine\");\n    Serial.print(\"   cpu \");\n    Serial.print(AudioProcessorUsageMax(), 1);\n    Serial.println(\"%\");\n    AudioProcessorUsageMaxReset();\n\n    /* Four bars of sixteenths at 96 bpm is exactly 10 seconds. */\n    delay(10000);\n  }\n}\n";
